 * Nothing here can confirm a sale. Confirmed is written by exactly one thing,
 * the notary's PURCHASE_COMPLETED outcome, for the same reason the reservation
 * list has no "marquer comme vendu" button.
 */
export function SalePanel({
  reservationId,
  reservationStatus,
  canManage,
}: {
  reservationId: string;
  /** Drives whether "Créer une vente" is offered — the API decides the rest. */
  reservationStatus: string;
  /** SALES_AGENT / PROJECT_ADMIN / GLOBAL_ADMIN — mirrors RoleGroups.AdminsAgents. */
  canManage: boolean;
}) {
  const [sale, setSale] = useState<Sale | null | undefined>(undefined);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [createOpen, setCreateOpen] = useState(false);
  const [editOpen, setEditOpen] = useState(false);

  const load = useCallback(async () => {
    const data = await salesApi.getByReservation(reservationId);
    setSale(data);
  }, [reservationId]);

  useEffect(() => {
    // An empty result means "no sale yet" — a normal state. Anything else is a
    // real failure and is shown, rather than being flattened into the same
    // empty view (the N19 mistake on the handover panel).
    load().catch((err) => {
      setSale(null);
      setError(err instanceof ApiError ? err.message : "Échec du chargement de la vente.");
    });
  }, [load]);

  async function create(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = new FormData(e.currentTarget);
    const price = String(form.get("finalPrice") || "");
    const date = String(form.get("saleDate") || "");

    setError(null);
    setBusy(true);
    try {
      await salesApi.createDraft({
        reservationId,
        // Omitted rather than sent empty: the API then snapshots the
        // reservation's own final price and uses the current date.
        saleDate: date ? new Date(date).toISOString() : undefined,
        finalPrice: price ? Number(price) : undefined,
        notes: String(form.get("notes") || "") || undefined,
      });
      setCreateOpen(false);
      await load();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Échec de la création de la vente.");
    } finally {
      setBusy(false);
    }
  }

  async function update(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!sale) return;
    const form = new FormData(e.currentTarget);
    const price = String(form.get("finalPrice") || "");
    const date = String(form.get("saleDate") || "");

    setError(null);
    setBusy(true);
    try {
      await salesApi.updateDraft(sale.id, {
        saleDate: date ? new Date(date).toISOString() : undefined,
        finalPrice: price ? Number(price) : undefined,
        notes: String(form.get("notes") || ""),
      });
      setEditOpen(false);
      await load();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Échec de la modification de la vente.");
    } finally {
      setBusy(false);
    }
  }

  async function cancel() {
    if (!sale) return;
    const reason = window.prompt(
      "Motif de l'annulation de la vente ?\n\nLa vente est conservée dans l'historique ; le bien et la réservation sont libérés."
    );
    if (reason === null) return;

    setError(null);
    setBusy(true);
    try {
      await salesApi.cancelDraft(sale.id, reason || undefined);
      await load();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Échec de l'annulation de la vente.");
    } finally {
      setBusy(false);
    }
  }

  if (sale === undefined) return <Loading />;

  // A sale is opened from an approved file. On a CONVERTED one the sale already
  // exists (the notary created or confirmed it), so the action is not offered
  // there either — only the record is shown.
  const canOfferCreate = canManage && reservationStatus === "APPROVED" && !isActive(sale);

  return (
    <Card>
      <div className="page-header" style={{ marginBottom: 12 }}>
        <h4 style={{ margin: 0 }}>Vente</h4>
        {canOfferCreate && (
==== PROJ FORM
      {showCreate && canManageProjects && (
        <Modal
          title="Nouveau projet"
          onClose={() => {
            if (creating) return;
            setShowCreate(false);
            resetCreateForm();
          }}
        >
          <form onSubmit={onCreate}>
            {createError && <p className="form-error" role="alert">{createError}</p>}
            <Field label="Nom"><input name="name" required disabled={creating} /></Field>
            <Field label="Localisation"><input name="location" required disabled={creating} /></Field>
            <Field label="Adresse"><input name="address" disabled={creating} /></Field>
            <Field label="Type">
              <select name="type">
                <option>Appartements</option>
                <option>Bureaux</option>
                <option>Studios</option>
              </select>
            </Field>
            <Field label="Statut">
              {/* Seuls les codes §3 que le backend legacy sait écrire honnêtement
                  (voir enums.ts). DRAFT est pourtant requis à la création
                  (FR-CMS-001) — lacune backend, pas un choix UI. */}
              <select name="statusGlobal">
                <option value="PLANNED">PLANNED</option>
                <option value="IN_PROGRESS">IN_PROGRESS</option>
              </select>
            </Field>
            <Field label="Garantie (mois)">
              {/* §8 — copiée et gelée sur chaque vente à sa création. Vide = 12 mois. */}
              <input name="warrantyMonths" type="number" min="1" max="360" placeholder="12" disabled={creating} />
            </Field>
            <Field label="Description"><textarea name="description" rows={3} disabled={creating} /></Field>

            <ImageUploadField label="Photos" value={images} onChange={setImages} />

            <Field label="Lien visite 3D">
              <input
                type="url"
                value={module3DLink}
                onChange={(e) => setModule3DLink(e.target.value)}
                placeholder="https://…"
                disabled={creating}
              />
            </Field>

            <Button type="submit" disabled={creating}>{creating ? "Création…" : "Créer"}</Button>
          </form>
        </Modal>
      )}
    </div>
  );
}

