  $r = Call $who $method $path $body
  $ok = $expect -contains $r.code
  $note = ""
  if (-not $ok -and $r.body) {
    try { $j = $r.body | ConvertFrom-Json; $note = "$($j.code) $($j.detail)$($j.message)$($j.title)" } catch { $note = $r.body }
    if ($note.Length -gt 180) { $note = $note.Substring(0,180) }
