import { execFileSync } from "node:child_process";
import { Api } from "./api";
import type { RoleKey } from "./accounts";

/**
 * Business-state fixtures built through the API, so a UI test only exercises
 * its own rule and never re-drives the whole upstream journey in the browser.
 *
 * Every helper creates fresh data (unique `e2e-…` names): tests never share a
 * project, unit or reservation, and never depend on execution order.
 */

export const uid = () => `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 7)}`;

const iso = (d: Date) => d.toISOString().slice(0, 19);
const daysFromNow = (days: number, hour = 10) => {
  const d = new Date();
  d.setDate(d.getDate() + days);
  d.setHours(hour, 0, 0, 0);
  return d;
};

/** Backend enums are serialised as integers. */
export const MilestoneStatus = { NotStarted: 0, InProgress: 1, Completed: 2 } as const;
export const AppointmentStatus = { Requested: 0, Confirmed: 1, RescheduleProposed: 2, Rejected: 3, Cancelled: 4, Completed: 5, NoShow: 6 } as const;
export const ClaimStatus = { Submitted: 0, UnderReview: 1, MoreInfoRequired: 2, Assigned: 3, InProgress: 4, WaitingCustomer: 5, Resolved: 6, Rejected: 7, Cancelled: 8, Closed: 9 } as const;

export type Phase = "SUR_PLAN" | "EN_LIVRAISON" | "FINALISE";

export interface ProjectFixture {
  id: string;
  name: string;
  immeubleId: string;
  floorId: string;
  unitIds: string[];
  milestoneIds: string[];
  warrantyMonths: number;
}

export interface JourneyFixture {
  project: ProjectFixture;
  unitId: string;
  reservationId: string;
  buyer: RoleKey;
  saleId?: string;
  notaryAppointmentId?: string;
  handoverId?: string;
  warrantyId?: string;
  claimId?: string;
  finalVisitAppointmentId?: string;
  finalVisitReportId?: string;
}

const admin = () => Api.as("globalAdmin");

/**
 * createProject(status, constructionPct).
 *
 * The project is created SUR_PLAN with two weighted milestones; `constructionPct`
 * of the weight is marked completed. Reaching EN_LIVRAISON requires 100 % and
 * goes through the real `complete` command; FINALISE through `finalize`.
 * Memberships attach the agent, notary, technician, tech lead and project admin
 * accounts so their perimeter covers this project (and only this one).
 */
export async function createProject(
  opts: {
    phase?: Phase;
    constructionPct?: number;
    warrantyMonths?: number;
    units?: number;
    members?: RoleKey[];
  } = {},
): Promise<ProjectFixture> {
  const phase = opts.phase ?? "SUR_PLAN";
  const pct = phase === "SUR_PLAN" ? (opts.constructionPct ?? 0) : 100;
  const members = opts.members ?? ["agent", "notary", "technician", "techLead", "projectAdmin"];
  const warrantyMonths = opts.warrantyMonths ?? 24;
  const a = await admin();
  const name = `e2e-${uid()}`;

  const project = await a.post<{ id: string }>("/api/Projects", {
    name,
    location: "Casablanca",
    address: "12 avenue E2E",
    description: "Projet E2E automatisé",
    statusGlobal: "IN_PROGRESS",
    warrantyMonths,
    images: [],
  });

  for (const key of members) {
    const member = await Api.as(key);
    await a.post("/api/ProjectMembership", { projectId: project.id, userId: member.userId, roleCode: member.s.roles.includes("TECH_LEAD") ? "TECH_LEAD" : roleCodeOf(key) });
  }

  const imm = await a.post<{ projectId: string }>("/api/Immeuble", {
    name: `${name}-B1`,
    projectId: project.id,
    location: "Casablanca",
    type: "Appartements",
    minPrice: 800000,
    maxPrice: 2000000,
    images: "",
    description: "Bâtiment E2E",
    latitude: 33.57,
    longitude: -7.59,
    status: "UnderConstruction",
    numberOfUnits: opts.units ?? 2,
    minSellableSurfaceRange: 60,
    maxSellableSurfaceRange: 140,
    numberOfSoldUnites: 0,
    numberOfAvailableUnites: opts.units ?? 2,
    sellsPercentage: 0,
  });
  // CreateImmeubleResponse names the new building's id "projectId".
  const immeubleId = imm.projectId;
  const floor = await a.post<{ floorId: string }>(`/api/Immeuble/${immeubleId}/floors`, { immeubleId, name: "RDC", sequenceNo: 0 });

  const unitIds: string[] = [];
  for (let i = 0; i < (opts.units ?? 2); i++) {
    const unit = await a.post<{ unitId: string }>(`/api/Immeuble/${immeubleId}/units`, {
      projectId: immeubleId,
      floorId: floor.floorId,
      unitNumber: `RDC-${i + 1}`,
      numberOfBedrooms: 2,
      numberOfBathrooms: 1,
      apartmentSurface: 95,
      view: "Jardin",
      orientation: "Sud",
      totalSurface: 105,
      price: 1250000,
    });
    unitIds.push(unit.unitId);
  }

  const milestoneIds: string[] = [];
  const done = await a.post<{ milestoneId: string }>(`/api/construction/projects/${project.id}/milestones`, {
    projectId: project.id,
    code: "GROS_OEUVRE",
    nameFr: "Gros œuvre",
    sequenceNo: 1,
    weightPercent: 50,
  });
  const rest = await a.post<{ milestoneId: string }>(`/api/construction/projects/${project.id}/milestones`, {
    projectId: project.id,
    code: "FINITIONS",
    nameFr: "Finitions",
    sequenceNo: 2,
    weightPercent: 50,
  });
  milestoneIds.push(done.milestoneId, rest.milestoneId);

  const fixture: ProjectFixture = { id: project.id, name, immeubleId, floorId: floor.floorId, unitIds, milestoneIds, warrantyMonths };
  await setConstructionPct(fixture, pct);
  if (phase === "EN_LIVRAISON" || phase === "FINALISE") await completeProject(fixture);
  if (phase === "FINALISE") await finalizeProject(fixture);
  return fixture;
}

function roleCodeOf(key: RoleKey): string {
  switch (key) {
    case "agent":
    case "agentOther":
      return "SALES_AGENT";
    case "notary":
      return "NOTARY";
    case "technician":
    case "technicianOther":
      return "TECHNICIAN";
    case "techLead":
      return "TECH_LEAD";
    case "projectAdmin":
      return "PROJECT_ADMIN";
    default:
      throw new Error(`No membership role for ${key}`);
  }
}

/** Marks milestones completed so the weighted progress equals pct (0, 50 or 100). */
export async function setConstructionPct(p: ProjectFixture, pct: number) {
  if (![0, 50, 100].includes(pct)) throw new Error(`constructionPct must be 0, 50 or 100 (got ${pct})`);
  const a = await admin();
  const completed = pct / 50;
  for (let i = 0; i < completed; i++) {
    await a.patch(`/api/construction/milestones/${p.milestoneIds[i]}/status`, {
      milestoneId: p.milestoneIds[i],
      status: MilestoneStatus.Completed,
      actualDate: iso(new Date()),
    });
  }
}

/** SUR_PLAN → EN_LIVRAISON through the real 100 % gate. */
export async function completeProject(p: ProjectFixture) {
  const a = await admin();
  await a.post(`/api/construction/projects/${p.id}/complete`, { projectId: p.id, confirm: true });
}

/** EN_LIVRAISON → FINALISE. */
export async function finalizeProject(p: ProjectFixture) {
  const a = await admin();
  await a.post(`/api/construction/projects/${p.id}/finalize`, { projectId: p.id, confirm: true });
}

export async function getProject(id: string, as: RoleKey = "globalAdmin") {
  const api = await Api.as(as);
  return api.get<{ id: string; name: string; statusGlobal: string; businessPhase?: string; warrantyMonths: number }>(`/api/Projects/${id}`);
}

/**
 * createReservation(state): SUBMITTED by default, APPROVED when asked
 * (approved by the global admin — the creating agent may not self-approve).
 */
export async function createReservation(
  p: ProjectFixture,
  opts: { state?: "DRAFT" | "SUBMITTED" | "APPROVED"; buyer?: RoleKey; unitIndex?: number; agent?: RoleKey } = {},
): Promise<JourneyFixture> {
  const buyerKey = opts.buyer ?? "buyer";
  const agent = await Api.as(opts.agent ?? "agent");
  const buyer = await Api.as(buyerKey);
  const unitId = p.unitIds[opts.unitIndex ?? 0];
  const res = await agent.post<{ reservationId: string }>("/api/Reservations/create", {
    buyerId: buyer.userId,
    name: "Yasmine",
    lastName: `E2E-${buyerKey}`,
    cin: `E2E${uid().slice(0, 6)}`,
    email: `${buyerKey}.${uid()}@example.test`,
    phoneNumber: "+212600112233",
    unitId,
    agentId: agent.userId,
    totalPropertyPrice: 1250000,
    reservationAmount: 125000,
    isUnderConstruction: true,
    createAsDraft: opts.state === "DRAFT",
    discount: 0,
  });
  const j: JourneyFixture = { project: p, unitId, reservationId: res.reservationId, buyer: buyerKey };
  if (opts.state === "APPROVED") await approveReservation(j);
  return j;
}

export async function approveReservation(j: JourneyFixture) {
  const a = await admin();
  await a.post(`/api/Reservations/${j.reservationId}/approve`, {
    reservationId: j.reservationId,
    adminUserId: a.userId,
    adminNote: "Approuvé (E2E)",
    documents: [],
  });
}

/**
 * createFinalVisit(result): buyer requests, agent confirms, admin authorises
 * early completion, agent files the report, buyer acknowledges it. The land
 * title is moved to AVAILABLE so the dossier becomes notary-eligible.
 * Requires the project to be EN_LIVRAISON (§ final visit gate).
 */
export async function createFinalVisit(j: JourneyFixture, result: "COMPLIANT" | "REQUESTED" = "COMPLIANT") {
  const buyer = await Api.as(j.buyer, true);
  const agent = await Api.as("agent");
  const a = await admin();
  const fv = await buyer.post<{ caseId: string; appointmentId: string }>(`/api/final-visits/reservations/${j.reservationId}/request`, {
    reservationId: j.reservationId,
    startsAt: iso(daysFromNow(2 + Math.floor(Math.random() * 60), 9 + Math.floor(Math.random() * 8))),
  });
  j.finalVisitAppointmentId = fv.appointmentId;
  if (result === "REQUESTED") return j;

  await agent.post(`/api/final-visits/appointments/${fv.appointmentId}/transition`, { appointmentId: fv.appointmentId, targetStatus: AppointmentStatus.Confirmed });
  await a.post(`/api/final-visits/appointments/${fv.appointmentId}/transition`, {
    appointmentId: fv.appointmentId,
    targetStatus: AppointmentStatus.Completed,
    allowEarlyCompletion: true,
  });
  const report = await agent.post<{ reportId: string }>(`/api/final-visits/appointments/${fv.appointmentId}/report`, {
    appointmentId: fv.appointmentId,
    resultCode: 0,
    generalCondition: "Conforme",
    observations: "Aucune réserve (E2E)",
    snags: [],
  });
  j.finalVisitReportId = report.reportId;
  await buyer.post(`/api/final-visits/reports/${report.reportId}/acknowledge`, { reportId: report.reportId });

  await a.patch(`/api/construction/units/${j.unitId}/title`, { unitId: j.unitId, status: 1, reason: "Dépôt conservation foncière (E2E)" });
  await a.patch(`/api/construction/units/${j.unitId}/title`, { unitId: j.unitId, status: 2, reason: "Titre obtenu (E2E)" });
  return j;
}

export async function createDraftSale(j: JourneyFixture, as: RoleKey = "agent") {
  const api = await Api.as(as);
  const sale = await api.post<{ id: string; status: string }>("/api/sales", { reservationId: j.reservationId, notes: "Vente E2E" });
  j.saleId = sale.id;
  return sale;
}

/**
 * createNotaryAppointment(result): booked by the agent for this project's
 * notary; with a result, confirmed then completed by the notary.
 */
export async function createNotaryAppointment(j: JourneyFixture, result?: "PURCHASE_COMPLETED" | "POSTPONED") {
  const agent = await Api.as("agent");
  const notary = await Api.as("notary");
  const buyer = await Api.as(j.buyer);
  const na = await agent.post<{ id: string }>("/api/NotaryAppointments", {
    reservationId: j.reservationId,
    notaireId: notary.userId,
    agentId: agent.userId,
    buyerId: buyer.userId,
    appointmentDate: iso(daysFromNow(5 + Math.floor(Math.random() * 600), 8 + Math.floor(Math.random() * 9))),
    status: "Scheduled",
    taxFees: 25000,
    tahfidFees: 8000,
  });
  j.notaryAppointmentId = na.id;
  if (result) {
    await notary.put(`/api/NotaryAppointments/${na.id}`, { id: na.id, status: "Confirmed" });
    await notary.put(`/api/NotaryAppointments/${na.id}`, {
      id: na.id,
      status: "Completed",
      outcome: result,
      outcomeNote: result === "PURCHASE_COMPLETED" ? "Acte signé (E2E)" : "Reporté (E2E)",
    });
  }
  return j;
}

/** deliverUnit(): handover scheduled, confirmed, reported, acknowledged by the buyer. */
export async function deliverUnit(j: JourneyFixture) {
  const agent = await Api.as("agent");
  const buyer = await Api.as(j.buyer, true);
  const ho = await agent.post<{ id: string }>("/api/Handovers", {
    reservationId: j.reservationId,
    scheduledAt: iso(daysFromNow(9)),
    location: "Sur site",
    notes: "Remise des clés (E2E)",
  });
  j.handoverId = ho.id;
  await agent.post(`/api/Handovers/${ho.id}/confirm`);
  const rep = await agent.post<{ id: string }>(`/api/Handovers/${ho.id}/report`, {
    appointmentId: ho.id,
    participants: "Acquéreur, agent",
    observations: "Logement conforme (E2E)",
    items: [{ itemType: "Clés", quantity: 2 }],
  });
  await buyer.post(`/api/Handovers/reports/${rep.id}/acknowledge`, {});
  return j;
}

export async function createClaim(j: JourneyFixture, title = `Fuite ${uid()}`) {
  const buyer = await Api.as(j.buyer, true);
  const claim = await buyer.post<{ id: string }>("/api/after-sales/claims", {
    unitId: j.unitId,
    title,
    description: "Infiltration constatée (E2E)",
    category: 2,
    priority: 1,
  });
  j.claimId = claim.id;
  return { id: claim.id, title };
}

/** Full journey up to a given stage, in dependency order. */
export async function journey(
  upTo: "APPROVED" | "FINAL_VISIT" | "DRAFT_SALE" | "SOLD" | "DELIVERED" | "CLAIM",
  opts: { buyer?: RoleKey; warrantyMonths?: number } = {},
): Promise<JourneyFixture> {
  const p = await createProject({ phase: "SUR_PLAN", warrantyMonths: opts.warrantyMonths });
  const j = await createReservation(p, { state: "APPROVED", buyer: opts.buyer });
  if (upTo === "APPROVED") return j;
  await setConstructionPct(p, 100);
  await completeProject(p);
  await createFinalVisit(j);
  if (upTo === "FINAL_VISIT") return j;
  await createDraftSale(j);
  if (upTo === "DRAFT_SALE") return j;
  await createNotaryAppointment(j, "PURCHASE_COMPLETED");
  if (upTo === "SOLD") return j;
  await deliverUnit(j);
  if (upTo === "DELIVERED") return j;
  await createClaim(j);
  return j;
}

/**
 * Time travel for the warranty: no API can age a warranty, so this moves its
 * end date into the past directly in the QA database. Used only to reach the
 * "warranty expired" state; the rule itself is still asserted through the API/UI.
 */
export function expireWarranty(unitId: string) {
  const db = process.env.E2E_PROJECT_DB ?? "GPIA_Project_QA";
  const server = process.env.E2E_SQL_SERVER ?? ".\\SQLEXPRESS";
  execFileSync(
    "sqlcmd",
    ["-S", server, "-d", db, "-I", "-b", "-Q", `SET NOCOUNT ON; UPDATE Warranties SET StartsAt = DATEADD(month,-30,GETUTCDATE()), EndsAt = DATEADD(day,-1,GETUTCDATE()) WHERE UnitId = '${unitId}'`],
    { stdio: "pipe" },
  );
}

