    setSavingEdit(true);
    try {
      await projectsApi.update(id, {
        name: String(form.get("name")),
        location: String(form.get("location")),
        address: String(form.get("address")),
        description: String(form.get("description")),
        type: String(form.get("type")),
        statusGlobal: form.get("statusGlobal") as ProjectStatus,
        // §8 — affects sales opened from now on; every existing sale carries
        // its own frozen copy and is untouched.
        warrantyMonths: Number(form.get("warrantyMonths")) || undefined,
        // Images and the 3D link are edited in the media panel, which owns the
        // uploader. Resending them unchanged here keeps this form from
        // clearing what that panel just saved.
        images: project.images ?? [],
        module3DLink: project.module3DLink,
      });
      setShowEdit(false);
      loadProject(); // re-read the persisted project so the admin view reflects it immediately
    } catch (err) {
      setEditError(err instanceof ApiError ? err.message : "Échec de l'enregistrement du projet.");
    } finally {
      setSavingEdit(false);
    }
  }

  if (project === undefined) return <Loading />;
  if (project === null)
    return (
      <p>
        Projet introuvable. <Link to="/admin/projects">Retour aux projets</Link>
      </p>
    );

  return (
            project.address || project.location
          )
        }
        actions={
          <>
            <Link to={`/admin/projects/${id}/explore`} className="btn btn-secondary" style={{ display: "inline-block", whiteSpace: "nowrap" }}>
              Explorer →
            </Link>
            {canManageProjects && (
              <Button variant="ghost" onClick={() => setShowEdit(true)}>Modifier</Button>
            )}
            {/* Pas de suppression : un projet porte réservations, paiements et
                historique — les données métier ne sont jamais supprimées depuis
                l'UI (§9, §6.3). Le cycle de vie se termine par ARCHIVED. */}
          </>
        }
      />

      <div className="detail-grid">
        <Card>
          <h3>Informations</h3>
          <dl className="detail-list">
            <dt>Statut</dt>
            <dd>{project.statusGlobal ? <StatusBadge status={project.statusGlobal} /> : "-"}</dd>
            <dt>Type</dt>
            <dd>{project.type ?? "-"}</dd>
            <dt>Avancement</dt>
            <dd>{project.overAllProgress}%</dd>
            <dt>Likes</dt>
            <dd>{project.numberLikes}</dd>
            <dt>Garantie</dt>
            <dd>{project.warrantyMonths} mois</dd>
            <dt>Quartier</dt>
            <dd>{project.quartierName ?? "-"}</dd>
            <dt>Agent(s)</dt>
            <dd>{project.assignedAgents.map((a) => a.fullName).join(", ") || "Non assigné"}</dd>
            <dt>Notaire(s)</dt>
            <dd>{project.assignedNotaries.map((a) => a.fullName).join(", ") || "Non assigné"}</dd>
          </dl>
          <p>{project.description}</p>
        </Card>

        <Card>
          <h3>Équipements</h3>
          {features.length === 0 ? <p className="muted">Aucun équipement enregistré.</p> : (
            <div className="feature-list">
              {features.map((f) => <span key={f.id} className="feature-chip">{f.name}</span>)}
            </div>
          )}
          <h3 style={{ marginTop: 20 }}>Types de biens</h3>
          <div className="feature-list">
            {project.typeBiens.map((t) => <span key={t.id} className="feature-chip">{t.name}</span>)}
          </div>
        </Card>
      </div>

      <Card>
        <div className="page-header" style={{ marginBottom: 12 }}>
          <h3 style={{ margin: 0 }}>Immeubles</h3>
          {canManageProjects && (
            <Button onClick={() => setShowCreateImmeuble(true)}>+ Nouveau bâtiment</Button>
          )}
        </div>
        <Table
          keyField={(im) => im.id}
          rows={immeubles}
          columns={[
            { header: "Nom", render: (im) => <Link to={`/admin/immeubles/${im.id}`}>{im.name}</Link> },
            { header: "Statut", render: (im) => (im.status ? <StatusBadge status={im.status} /> : "-") },
            { header: "Unités", render: (im) => im.numberOfUnits, align: "right" },
            { header: "Disponibles", render: (im) => im.numberOfAvailableUnites, align: "right" },
            { header: "Prix", render: (im) => `${formatMAD(im.minPrice)} - ${formatMAD(im.maxPrice)}` },
          ]}
        />
      </Card>

      {showEdit && canManageProjects && (
        <Modal
          title="Modifier le projet"
          onClose={() => {
            if (!savingEdit) setShowEdit(false);
          }}
        >
          <form onSubmit={onEdit}>
            {editError && <p className="form-error" role="alert">{editError}</p>}
            <Field label="Nom"><input name="name" defaultValue={project.name} required disabled={savingEdit} /></Field>
            <Field label="Localisation"><input name="location" defaultValue={project.location} required disabled={savingEdit} /></Field>
            <Field label="Adresse"><input name="address" defaultValue={project.address ?? ""} disabled={savingEdit} /></Field>
            <Field label="Type"><input name="type" defaultValue={project.type ?? ""} disabled={savingEdit} /></Field>
            <Field label="Statut">
              {/* Seuls les codes §3 que le backend legacy sait écrire honnêtement
                  (voir enums.ts). COMPLETED déverrouille les visites finales (§5.6)
                  et n'a pas de valeur legacy honnête ; DRAFT est pourtant requis à
                  la création (FR-CMS-001) — lacune backend, pas un choix UI. */}
              <select name="statusGlobal" defaultValue={project.statusGlobal ?? "PLANNED"} disabled={savingEdit}>
                <option value="PLANNED">PLANNED</option>
                <option value="IN_PROGRESS">IN_PROGRESS</option>
              </select>
            </Field>
            <Field label="Garantie (mois)">
              {/* §8 — la durée est copiée et gelée sur chaque vente à sa
                  création : la modifier ici ne raccourcit ni n'allonge une
                  garantie déjà accordée. */}
              <input
                name="warrantyMonths"
                type="number"
                min="1"
                max="360"
                defaultValue={project.warrantyMonths}
                disabled={savingEdit}
              />
            </Field>
            <Field label="Description"><textarea name="description" rows={3} defaultValue={project.description ?? ""} disabled={savingEdit} /></Field>
            <Button type="submit" disabled={savingEdit}>
              {savingEdit ? "Enregistrement…" : "Enregistrer"}
            </Button>
          </form>
        </Modal>
      )}
    </div>
  );
}

