test.describe("Acheteur", { tag: "@buyer" }, () => {
  test("buyer_sees_only_own_reservations_sales_visits_appointments_warranties_claims", async ({ page }) => {
    test.setTimeout(180_000);
    const mine = await st.journey("CLAIM", { buyer: "buyer" });
    const theirs = await st.journey("CLAIM", { buyer: "buyerOther" });
    const buyer = await Api.as("buyer", true);

    // 1. Reservations — list and direct URL.
    const reservations = await buyer.get<{ id: string }[]>("/api/Reservations/mine");
    expect(reservations.map((r) => r.id)).toContain(mine.reservationId);
    expect(reservations.map((r) => r.id)).not.toContain(theirs.reservationId);
    await page.goto("/my/properties");
    await expect(page.locator(`a[href="/my/properties/${mine.reservationId}"]`)).toHaveCount(1);
    await expect(page.locator(`a[href="/my/properties/${theirs.reservationId}"]`)).toHaveCount(0);
    await page.goto(`/my/properties/${theirs.reservationId}`);
    await expect(page.getByRole("heading", { name: "Dossier introuvable" })).toBeVisible();

    // 2. Sales.
    expect((await buyer.get<{ id: string }>(`/api/sales/by-reservation/${mine.reservationId}`)).id).toBeTruthy();
    await expectRefused(await buyer.raw("GET", `/api/sales/by-reservation/${theirs.reservationId}`), [403, 404], "other buyer's sale");
    const otherBuyer = await Api.as("buyerOther", true);
    await expectRefused(await buyer.raw("GET", `/api/sales/user/${otherBuyer.userId}`), [403], "other buyer's sales by user");

    // 3. Final visits.
    await buyer.get(`/api/final-visits/reservations/${mine.reservationId}/report/mine`);
    await expectRefused(await buyer.raw("GET", `/api/final-visits/reservations/${theirs.reservationId}/report/mine`), [403, 404], "other buyer's visit report");

    // 4. Notary appointments.
    const appts = await buyer.get<{ data: { id: string; reservationId: string }[] }>("/api/NotaryAppointments?PageSize=500");
    expect(appts.data.map((a) => a.id)).toContain(mine.notaryAppointmentId);
    expect(appts.data.map((a) => a.id)).not.toContain(theirs.notaryAppointmentId);
    await expectRefused(await buyer.raw("GET", `/api/NotaryAppointments/${theirs.notaryAppointmentId}`), [403, 404], "other buyer's notary appointment");

    // 5. Warranties.
    expect((await buyer.get<unknown[]>(`/api/Handovers/reservations/${mine.reservationId}/warranties/mine`)).length).toBe(1);
    const otherWarranties = await buyer.raw("GET", `/api/Handovers/reservations/${theirs.reservationId}/warranties/mine`);
    if (otherWarranties.ok()) expect(await otherWarranties.json()).toEqual([]);
    else await expectRefused(otherWarranties, [403, 404], "other buyer's warranties");

    // 6. Claims — list (API and UI).
    const claims = await buyer.get<{ data: { id: string }[] }>("/api/after-sales/claims/mine");
    expect(claims.data.map((c) => c.id)).toContain(mine.claimId);
    expect(claims.data.map((c) => c.id)).not.toContain(theirs.claimId);
    const mineTitle = (await st.getClaim(mine.claimId!))!.title;
    const theirTitle = (await st.getClaim(theirs.claimId!))!.title;
    await page.goto("/my/sav");
    await expect(page.getByRole("row").filter({ hasText: mineTitle })).toHaveCount(1);
    await expect(page.getByRole("row").filter({ hasText: theirTitle })).toHaveCount(0);
  });

