test.describe("Responsable technique", { tag: "@techLead" }, () => {
  test("tech_lead_can_assign_claim_to_technician", async ({ page }) => {
    const j = await st.journey("CLAIM");
    const claim = (await st.getClaim(j.claimId!))!;
    const tech = await Api.as("technician");

    await page.goto("/admin/claims");
    const row = page.getByRole("row").filter({ hasText: claim.title });
    await row.getByRole("button", { name: "Mettre en cours d'analyse" }).click();
    await row.getByRole("button", { name: "Affecter un technicien" }).click();
    const dialog = page.getByRole("dialog", { name: "Affecter un technicien" });
    await dialog.getByLabel("Technicien").selectOption(tech.userId);
    await expect(dialog).toBeHidden();

    await expect.poll(async () => (await st.getClaim(j.claimId!))?.status).toBe(st.ClaimStatus.Assigned);
    expect((await st.getClaim(j.claimId!))?.assignedAgentId).toBe(tech.userId);
  });

  test("tech_lead_can_validate_claim_closure", async ({ page }) => {
    const j = await st.journey("CLAIM");
    await st.advanceClaim(j, "RESOLVED");
    const claim = (await st.getClaim(j.claimId!))!;

    await page.goto("/admin/claims");
    await page.getByRole("row").filter({ hasText: claim.title }).getByRole("button", { name: "Valider la clôture" }).click();
    await expect.poll(async () => (await st.getClaim(j.claimId!))?.status).toBe(st.ClaimStatus.Closed);
  });
});

test.describe("Technicien", { tag: "@technician" }, () => {
  test("technician_sees_only_assigned_claims", async ({ page }) => {
    const members = ["agent", "notary", "technician", "technicianOther", "techLead", "projectAdmin"] as const;
    const assignedToMe = await st.journey("CLAIM", { members: [...members] });
    const assignedToOther = await st.journey("CLAIM", { members: [...members] });
    await st.advanceClaim(assignedToMe, "ASSIGNED", "technician");
    await st.advanceClaim(assignedToOther, "ASSIGNED", "technicianOther");
    const myTitle = (await st.getClaim(assignedToMe.claimId!))!.title;
    const otherTitle = (await st.getClaim(assignedToOther.claimId!))!.title;

    await page.goto("/admin/claims");
    await expect(page.getByRole("row").filter({ hasText: myTitle })).toHaveCount(1);
    await expect(page.getByRole("row").filter({ hasText: otherTitle })).toHaveCount(0);

    const tech = await Api.as("technician");
    const list = await tech.get<{ data: { id: string; assignedAgentId?: string }[] }>("/api/after-sales/claims?PageSize=1000");
    expect(list.data.map((c) => c.id)).toContain(assignedToMe.claimId);
    expect(list.data.map((c) => c.id)).not.toContain(assignedToOther.claimId);
    expect(list.data.every((c) => c.assignedAgentId === tech.userId)).toBe(true);
  });

  test("technician_cannot_validate_closure", async ({ page }) => {
    const j = await st.journey("CLAIM");
    await st.advanceClaim(j, "RESOLVED", "technician");
    const claim = (await st.getClaim(j.claimId!))!;

    await page.goto("/admin/claims");
    const row = page.getByRole("row").filter({ hasText: claim.title });
    await expect(row).toHaveCount(1);
    await expect(row.getByRole("button", { name: "Valider la clôture" })).toHaveCount(0);

    const tech = await Api.as("technician");
    await expectRefused(
      await tech.raw("PUT", `/api/after-sales/claims/${j.claimId}/status`, { claimId: j.claimId, newStatus: st.ClaimStatus.Closed }),
      [403],
      "technician closes claim",
    );
    expect((await st.getClaim(j.claimId!))?.status).toBe(st.ClaimStatus.Resolved);
  });
});

