import type { PageQuery, PaginatedResponse } from "../types";

/**
 * Loads every page of a paginated list endpoint and returns them as one
 * response.
 *
 * Screens with no paging controls used to request a single page (50 or 100
 * rows) and silently drop the rest: past that size, new projects, reservations,
 * claims or appointments simply vanished from tables and dropdowns. Use this
 * wherever a screen shows or picks from "the whole list".
 */
export async function allPages<T, Q extends PageQuery>(
  fetchPage: (query: Q) => Promise<PaginatedResponse<T>>,
  query: Omit<Q, "pageNumber" | "pageSize"> = {} as Omit<Q, "pageNumber" | "pageSize">,
  pageSize = 200,
): Promise<PaginatedResponse<T>> {
  const first = await fetchPage({ ...query, pageNumber: 1, pageSize } as Q);
  const data = [...first.data];
  const totalPages = Math.max(1, first.totalPages ?? 1);
  for (let pageNumber = 2; pageNumber <= totalPages; pageNumber++) {
    const page = await fetchPage({ ...query, pageNumber, pageSize } as Q);
    data.push(...page.data);
  }
  return { pageNumber: 1, pageSize: data.length, totalItems: first.totalItems ?? data.length, totalPages: 1, data };
}

