import { useCallback, useEffect, useRef, useState } from "react";
import { reservationsApi } from "../../api";
import { ApiError } from "../../api/http/client";
import type { ReservationChecklist, ReservationDocument } from "../../types";
import { formatDateTime } from "../../lib/format";

const DOCUMENT_TYPES = ["Contract", "CIN", "Blueprint", "Other"] as const;
const DOCUMENT_TYPE_LABEL: Record<string, string> = {
  Contract: "Contrat",
  CIN: "CIN",
  Blueprint: "Plan",
  Other: "Autre",
};

/**
 * Upload path existed backend-side (ReservationDocument entity, read by
 * GetReservationById) with nothing in the UI ever reaching it — this closes
 * that gap. Same self-contained per-reservation panel shape as HandoverPanel:
 * own loading/error state, no admin-wide list endpoint to back a global view.
 */
export function ReservationDocumentsPanel({
  reservationId,
  documents,
  onChange,
  canManage,
}: {
  reservationId: string;
  documents: ReservationDocument[];
  onChange: (documents: ReservationDocument[]) => void;
  canManage: boolean;
}) {
  const inputRef = useRef<HTMLInputElement | null>(null);
  const [documentType, setDocumentType] = useState<string>(DOCUMENT_TYPES[0]);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [checklist, setChecklist] = useState<ReservationChecklist | null>(null);
  const [openingId, setOpeningId] = useState<string | null>(null);

  async function openDocument(doc: ReservationDocument) {
    setError(null);
    setOpeningId(doc.id);
    try {
      const blob = await reservationsApi.downloadDocument(doc.id);
      const url = URL.createObjectURL(blob);
      window.open(url, "_blank", "noopener");
      // Released once the new tab has taken its own reference; revoking
      // immediately would race the open in some browsers.
      setTimeout(() => URL.revokeObjectURL(url), 60_000);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Échec de l'ouverture du document.");
    } finally {
      setOpeningId(null);
    }
  }


  // §12.1 — the project's own requirements. The list is computed server-side
  // (matching is case-insensitive on documentType, and the rule lives with the
  // submit endpoint that enforces it) so this panel never re-derives it: a
  // client-side copy would drift and show a satisfied checklist next to a 422.
  const loadChecklist = useCallback(async () => {
    setChecklist(await reservationsApi.getDocumentChecklist(reservationId));
  }, [reservationId]);

  useEffect(() => {
    // A project that configures no requirements returns an empty list; that is
    // the normal case and renders nothing at all.
    loadChecklist().catch(() => setChecklist(null));
  }, [loadChecklist]);

  async function handleFile(file: File | null) {
    if (!file) return;
    setBusy(true);
    setError(null);
    try {
      const document = await reservationsApi.uploadDocument(reservationId, file, documentType);
      onChange([...documents, document]);
      // What is still missing has just changed.
      await loadChecklist().catch(() => undefined);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Échec de l'envoi du document.");
    } finally {
      setBusy(false);
      if (inputRef.current) inputRef.current.value = "";
    }
  }

  async function handleDelete(document: ReservationDocument) {
    if (!window.confirm(`Supprimer « ${document.name ?? "ce document"} » ?`)) return;
    setError(null);
    setDeletingId(document.id);
    try {
      await reservationsApi.deleteDocument(document.id);
      onChange(documents.filter((d) => d.id !== document.id));
      await loadChecklist().catch(() => undefined);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Échec de la suppression du document.");
    } finally {
      setDeletingId(null);
    }
  }

  return (
    <div>
      <h4 style={{ marginTop: 20, marginBottom: 10 }}>Documents</h4>

      {error && <p className="form-error" style={{ marginBottom: 10 }}>{error}</p>}

      {checklist && checklist.items.length > 0 && (
        <div className="checklist" style={{ marginBottom: 12 }}>
          <p className="muted small" style={{ marginTop: 0 }}>
            {checklist.canSubmit
              ? "Toutes les pièces obligatoires de ce projet sont fournies."
              : "Ce projet exige des pièces qui manquent encore — la soumission sera refusée."}
          </p>
          <ul className="plain-list">
            {checklist.items.map((item) => (
              <li key={item.documentType} className="checklist-item">
                <span className={item.isProvided ? "checklist-mark is-done" : "checklist-mark"} aria-hidden="true">
                  {item.isProvided ? "✓" : "○"}
                </span>
                <span>{item.labelFr}</span>
                {!item.isRequired && <span className="muted small">facultatif</span>}
              </li>
            ))}
          </ul>
        </div>
      )}

      {documents.length === 0 ? (
        <p className="muted small">Aucun document pour cette réservation.</p>
      ) : (
        <ul className="document-list">
          {documents.map((doc) => (
            <li key={doc.id} className="document-list-item">
              {/* Not <a href={doc.url}>: that is a private blob address and is
                  not browsable. The file is streamed through the API, which is
                  what applies the perimeter check to the document itself. */}
              <button
                type="button"
                className="btn-link"
                onClick={() => openDocument(doc)}
                disabled={openingId === doc.id}
              >
                {openingId === doc.id ? "Ouverture…" : doc.name ?? "Document"}
              </button>
              <span className="muted small">{formatDateTime(doc.uploadedAt)}</span>
              {canManage && (
                <button
                  type="button"
                  className="btn btn-ghost"
                  onClick={() => handleDelete(doc)}
                  disabled={deletingId === doc.id}
                >
