async function openCreateReservation() {
  setCreateError(null);
  setCreateOpen(true);
  if (projects) return;
  try {
    const [projectList, types] = await Promise.all([
      allPages((page) => projectsApi.list({ ...page })),
      // The type-bien referential is optional: when it is empty the step is
      // skipped rather than shown as a dead dropdown.
      typeBiensApi.list().catch(() => [] as TypeBien[]),
    ]);
    setProjects(projectList.data);
    setTypeBiens(types.filter((type) => type.active !== false));
  } catch (err) {
    setCreateError(err instanceof Error ? err.message : "Impossible de charger les projets.");
  }
}

async function selectProject(projectId: string) {
  setSelectedProjectId(projectId);
  setSelectedImmeubleId("");
  setSelectedTypeBienId("");
  setSelectedFloor("");
  setAvailableUnits(null);
  resetUnitChoice();
  setImmeubles(null);
  if (!projectId) return;
  try {
    const res = await allPages((page) => immeublesApi.list({ ...page, projectId }));
    setImmeubles(res.data);
  } catch (err) {
    setCreateError(err instanceof Error ? err.message : "Impossible de charger les immeubles.");
  }
}

async function selectImmeuble(immeubleId: string) {
  setSelectedImmeubleId(immeubleId);
  setSelectedTypeBienId("");
  setSelectedFloor("");
  resetUnitChoice();
  setAvailableUnits(null);
  if (!immeubleId) return;
  setLoadingUnits(true);
  try {
    const units = await immeublesApi.listUnits(immeubleId);
    // Availability is the server's word (§3): we only narrow the list, never
    // infer that a unit is free from anything else.
    setAvailableUnits(units.filter((unit) => unit.status === "AVAILABLE"));
  } catch (err) {
    setCreateError(err instanceof Error ? err.message : "Impossible de charger les biens.");
  } finally {
    setLoadingUnits(false);
  }
}

function resetUnitChoice() {
  setSelectedUnitId("");
  setPropertyPrice("");
  setReservationAmount("");
  setDiscount("");
  setCoBuyers([]);
}

function addCoBuyer() {
  setCoBuyers((prev) => [...prev, { name: "", lastName: "", ownershipPercent: undefined }]);
}

