async function createReservation(event: FormEvent<HTMLFormElement>) {
  event.preventDefault();
  if (!user || !selectedUnitId) return;
  const form = new FormData(event.currentTarget);
  const totalPropertyPrice = Number(propertyPrice);
  const amount = Number(reservationAmount);
  const discountValue = discount ? Number(discount) : 0;
  if (!Number.isFinite(totalPropertyPrice) || totalPropertyPrice <= 0 || !Number.isFinite(amount) || amount <= 0) {
    setCreateError("Enter a valid total price and reservation amount.");
    return;
  }
  if (!Number.isFinite(discountValue) || discountValue < 0) {
    setCreateError("La remise doit être un montant positif ou nul.");
    return;
  }
  // §5.3 — when any ownership percentages are set, primary buyer + all
  // co-buyers must total 100%. Checked here so the agent sees a clear
  // message instead of a raw 422 from the backend's own validation.
  const percentagesUsed = coBuyers.some((c) => c.ownershipPercent != null);
  if (percentagesUsed) {
    const total = coBuyers.reduce((sum, c) => sum + (c.ownershipPercent ?? 0), 0);
    if (Math.abs(total - 100) > 0.01 && coBuyers.length > 0) {
      // Only the co-buyers' own share is known client-side (the primary
      // buyer's implied share isn't collected in this form); still warn
      // if co-buyers alone already exceed 100%, an unambiguous error.
      if (total > 100) {
        setCreateError("La somme des pourcentages de propriété des co-acquéreurs dépasse 100%.");
        return;
      }
    }
  }

  setCreating(true);
  setCreateError(null);
  try {
    await reservationsApi.create({
      name: String(form.get("name") ?? "").trim(),
      lastName: String(form.get("lastName") ?? "").trim(),
      cin: String(form.get("cin") ?? "").trim() || undefined,
      email: String(form.get("email") ?? "").trim() || undefined,
      phoneNumber: String(form.get("phoneNumber") ?? "").trim() || undefined,
      unitId: selectedUnitId,
      agentId: user.id,
      totalPropertyPrice,
      reservationAmount: amount,
      isUnderConstruction: form.get("isUnderConstruction") === "on",
      discount: discountValue || undefined,
      coBuyers: coBuyers.length > 0 ? coBuyers.filter((c) => c.name || c.lastName) : undefined,
      createAsDraft: createAsDraft || undefined,
    });
    setCreateOpen(false);
    setSelectedUnitId("");
    setPropertyPrice("");
    setReservationAmount("");
    setDiscount("");
    setCoBuyers([]);
    setCreateAsDraft(false);
    reload();
  } catch (err) {
    setCreateError(err instanceof Error ? err.message : "Unable to create the reservation.");
  } finally {
    setCreating(false);
  }
}

