return (
  <Card>
    <h3>Pièces exigées à la réservation</h3>
    <p className="muted small">
      Tant que cette liste est vide, aucune pièce n'est exigée et les réservations se soumettent
      comme aujourd'hui. Une pièce marquée obligatoire bloque la soumission tant qu'elle n'est pas
      jointe — les réservations déjà approuvées ne sont pas affectées.
    </p>

    {error && <p className="form-error">{error}</p>}

    {items === null ? (
      <Loading />
    ) : (
      <Table
        keyField={(item) => item.id}
        rows={items}
        emptyLabel="Aucune pièce exigée — la soumission n'est bloquée par aucun document."
        columns={[
          { header: "Pièce", render: (item) => item.labelFr },
          { header: "Code", render: (item) => <code>{item.documentType}</code> },
          {
            header: "Exigence",
            render: (item) => (
              <span className={`badge ${item.isRequired ? "badge-warning" : "badge-neutral"}`}>
                {item.isRequired ? "Obligatoire" : "Facultative"}
              </span>
            ),
          },
          {
            header: "",
            render: (item) => (
              <span style={{ display: "flex", gap: 8 }}>
                <button className="btn btn-ghost" onClick={() => toggleRequired(item)} disabled={busy}>
                  {item.isRequired ? "Rendre facultative" : "Rendre obligatoire"}
                </button>
                <button className="btn btn-ghost" onClick={() => remove(item)} disabled={busy}>
                  Retirer
                </button>
              </span>
            ),
          },
        ]}
      />
    )}

    <form onSubmit={add} className="inline-form" style={{ marginTop: 12 }}>
      <Field label="Code">
        {/* Matched against the type chosen when a document is uploaded
            (insensible à la casse côté serveur). */}
        <input name="documentType" required maxLength={100} placeholder="CIN" style={{ width: 120 }} />
      </Field>
      <Field label="Libellé">
        <input name="labelFr" required maxLength={200} placeholder="Copie de la CIN" style={{ minWidth: 220 }} />
      </Field>
      <label className="field">
        <span>
          <input name="isRequired" type="checkbox" defaultChecked disabled={busy} /> Obligatoire
        </span>
      </label>
      <Button type="submit" disabled={busy}>
        Ajouter
      </Button>
    </form>
  </Card>
);

