    await dialog.getByRole("button", { name: "Créer la réservation" }).click();
    await expect(dialog).toBeHidden();

    await expect.poll(orNull(async () => (await findByLastName(lastName))?.id ?? null)).not.toBeNull();
    const created = await reservation((await findByLastName(lastName))!.id);
    expect(created.documents).toHaveLength(3);
    expect(created.status).toBe(STATUS.SUBMITTED);
  });

  test("uploaded_documents_visible_in_detail_view", async ({ page }) => {
    const p = await st.createProject();
    const j = await st.createReservation(p, { state: "DRAFT" });
    await st.uploadReservationDocument(j.reservationId, "CIN", "agent", "piece-identite-e2e.pdf");

    const detail = await openReservation(page, p.name, j.buyerLastName);
    await expect(detail.getByRole("button", { name: "piece-identite-e2e.pdf" })).toBeVisible();
  });

  test("documents_can_be_added_and_deleted_in_detail_view", async ({ page }) => {
    acceptDialogs(page);
    const p = await st.createProject();
    const draft = await st.createReservation(p, { state: "DRAFT", unitIndex: 0 });

    const detail = await openReservation(page, p.name, draft.buyerLastName);
    await detail.getByLabel("Ajouter un document").setInputFiles(pdf("ajout-e2e.pdf"));
    await expect(detail.getByRole("button", { name: "ajout-e2e.pdf" })).toBeVisible();
    await expect.poll(async () => (await reservation(draft.reservationId)).documents.length).toBe(1);

    const item = detail.locator("li").filter({ has: page.getByRole("button", { name: "ajout-e2e.pdf" }) });
    await item.getByRole("button", { name: "Supprimer" }).click();
    await expect(detail.getByRole("button", { name: "ajout-e2e.pdf" })).toHaveCount(0);
    await expect.poll(async () => (await reservation(draft.reservationId)).documents.length).toBe(0);

    // On an approved file: adding stays possible, deleting is not offered and is refused by the API.
    const approved = await st.createReservation(p, { state: "APPROVED", unitIndex: 1 });
    const doc = await st.uploadReservationDocument(approved.reservationId, "OTHER", "agent", "approuve-e2e.pdf");
    await page.keyboard.press("Escape");
    const approvedDetail = await openReservation(page, p.name, approved.buyerLastName);
    await expect(approvedDetail.getByRole("button", { name: "approuve-e2e.pdf" })).toBeVisible();
    await expect(approvedDetail.locator("li").filter({ hasText: "approuve-e2e.pdf" }).getByRole("button", { name: "Supprimer" })).toHaveCount(0);
    await expect(approvedDetail.getByLabel("Ajouter un document")).toBeVisible();
    const agent = await Api.as("agent");
    await expectRefused(await agent.raw("DELETE", `/api/Reservations/documents/${doc.id}`), [409], "delete document on approved file");
    expect((await reservation(approved.reservationId)).documents).toHaveLength(1);
  });

  test("document_upload_does_not_return_403", async ({ page }) => {
    const p = await st.createProject();
    const j = await st.createReservation(p, { state: "DRAFT" });
    const detail = await openReservation(page, p.name, j.buyerLastName);
    const [response] = await Promise.all([
      page.waitForResponse((r) => r.request().method() === "POST" && r.url().includes(`/api/Reservations/${j.reservationId}/documents`)),
      detail.getByLabel("Ajouter un document").setInputFiles(pdf("statut-http.pdf")),
    ]);
    expect(response.status(), await response.text()).toBe(200);
    await expect(detail.getByRole("button", { name: "statut-http.pdf" })).toBeVisible();
    await expect(detail.getByRole("alert")).toHaveCount(0);
  });

  test("documents_persist_server_side_after_reload", async ({ page, browser }) => {
    const p = await st.createProject();
    const j = await st.createReservation(p, { state: "DRAFT" });
    const detail = await openReservation(page, p.name, j.buyerLastName);
    await detail.getByLabel("Ajouter un document").setInputFiles(pdf("persiste-e2e.pdf"));
    await expect(detail.getByRole("button", { name: "persiste-e2e.pdf" })).toBeVisible();

    // A brand-new browser context: nothing local survives, only the server.
    const fresh = await browser.newContext({ storageState: storageStateFor("agent") });
    const freshPage = await fresh.newPage();
    const freshDetail = await openReservation(freshPage, p.name, j.buyerLastName);
    await expect(freshDetail.getByRole("button", { name: "persiste-e2e.pdf" })).toBeVisible();
    await fresh.close();

    const docs = (await reservation(j.reservationId)).documents;
    expect(docs.map((d) => d.fileName ?? d.name)).toContain("persiste-e2e.pdf");
  });
});

