import { expect, test, type Locator, type Page } from "@playwright/test";
import { Api, expectRefused, orNull } from "./support/api";
import { storageStateFor } from "./support/accounts";
import * as st from "./support/state";
import { acceptDialogs, openReservation } from "./support/ui";

/**
 * Scope 4 — Réservations et documents.
 * Reservation status on the wire: 0 SUBMITTED, 1 APPROVED, 5 DRAFT, 6 CHANGES_REQUESTED.
 */
const STATUS = { SUBMITTED: 0, APPROVED: 1, DRAFT: 5, CHANGES_REQUESTED: 6 } as const;

const pdf = (name: string) => ({ name, mimeType: "application/pdf", buffer: Buffer.from(`%PDF-1.4 ${name}`) });

async function reservation(id: string, as: "agent" | "projectAdmin" | "globalAdmin" = "globalAdmin") {
  const api = await Api.as(as);
  return api.get<{ id: string; status: number; phoneNumber: string; documents: { id: string; fileName?: string; name?: string; documentType?: string }[] }>(
    `/api/Reservations/${id}`,
  );
}

async function openCreateForm(page: Page) {
  await page.goto("/admin/reservations");
  await page.getByRole("button", { name: "Créer une réservation" }).click();
  const dialog = page.getByRole("dialog", { name: "Créer une réservation" });
  await expect(dialog.getByLabel("Projet")).toBeVisible();
  return dialog;
}

async function fillBuyer(dialog: Locator, lastName: string) {
  await dialog.getByLabel("Prénom de l'acheteur", { exact: true }).fill("Imane");
  await dialog.getByLabel("Nom de l'acheteur", { exact: true }).fill(lastName);
  await dialog.getByLabel("CIN").first().fill(`E2E${st.uid().slice(0, 6)}`);
  await dialog.getByLabel("E-mail").first().fill(`${lastName.toLowerCase()}@example.test`);
  await dialog.getByLabel("Téléphone").first().fill("+212600000002");
  await dialog.getByLabel("Prix total (MAD)").fill("1250000");
  await dialog.getByLabel("Montant de réservation (MAD)").fill("125000");
}

async function findByLastName(lastName: string) {
  const agent = await Api.as("agent");
  const rows = await agent.all<{ id: string; lastName: string }>("/api/Reservations/list");
  return rows.find((r) => r.lastName === lastName);
}

