        {
            CaseId = visitCase.Id,
            AppointmentId = appointment.Id,
            AttemptNo = attemptNo,
            Message = attemptNo == 1
                ? "Demande de visite finale enregistrée."
                : $"Nouvelle tentative de visite finale (n°{attemptNo}) enregistrée."
        };
    }

    public async Task<SubmitFinalVisitReportResponse> Handle(
