import { useCallback, useEffect, useState, type FormEvent } from "react";
import {
  finalVisitsApi,
  NOTARY_ELIGIBILITY_LABEL,
  SNAG_SEVERITY_LABEL,
  SNAG_STATUS_LABEL,
  VISIT_RESULT_LABEL,
  type AppointmentAttemptStatus,
  type NotaryEligibility,
  type SnagInput,
  type SnagSeverity,
  type SnagStatus,
  type VisitResult,
} from "../../api/http/finalVisitsApi";
import { ApiError } from "../../api/http/client";
import { Button, Card, Field, Loading, StatusBadge } from "../../components/ui";
import { formatDateTime } from "../../lib/format";
import { useAuth } from "../../context/AuthContext";
import { ADMINS_AGENTS, BUYERS } from "../../lib/roles";
import type { InternalFinalVisitCase, MyFinalVisitReport } from "../../types";

/**
 * Final visit / réception (spec §17) and notary eligibility (§17.6).
 *
 * This panel is intentionally simple: it drives the case through
 * request → confirm → report → snags, all state-machine gated server-side.
 * `NotaryEligibility` is always re-fetched from the API, never computed here.
 *
 * The current appointment/report/snag ids come from finalVisitsApi.getCase —
 * every write below used to ask the caller to type one of these GUIDs by
 * hand (window.prompt), with no screen anywhere that ever showed them one to
 * copy (N11). The panel now holds the real case and resolves ids itself.
 */
export function FinalVisitPanel({ reservationId }: { reservationId: string }) {
  const { user } = useAuth();
  const canManageVisit = !!user?.roles.some((role) => (ADMINS_AGENTS as string[]).includes(role));
  const isBuyer = !!user?.roles.some((role) => (BUYERS as string[]).includes(role));
  const [eligibility, setEligibility] = useState<NotaryEligibility | null>(null);
  const [visitCase, setVisitCase] = useState<InternalFinalVisitCase | null>(null);
  const [buyerReport, setBuyerReport] = useState<MyFinalVisitReport | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [showReportForm, setShowReportForm] = useState(false);
  const [draftSnags, setDraftSnags] = useState<SnagInput[]>([]);

  const load = useCallback(async () => {
    // Buyers cannot call the internal /case endpoint. Their own report is
    // exposed through /report/mine instead; using the correct read prevents a
    // valid buyer file from being trapped on the loading state by a 403.
    const [data, caseData, myReport] = await Promise.all([
      finalVisitsApi.getNotaryEligibility(reservationId),
      canManageVisit ? finalVisitsApi.getCase(reservationId) : Promise.resolve(null),
      isBuyer ? finalVisitsApi.getMyReport(reservationId) : Promise.resolve(null),
    ]);
    setEligibility(data);
    setVisitCase(caseData);
    setBuyerReport(myReport);
  }, [reservationId, canManageVisit, isBuyer]);

  useEffect(() => {
    load().catch((err) => {
      setEligibility(null);
      setError(err instanceof ApiError ? err.message : "Impossible de charger la visite finale.");
    });
  }, [load]);

  async function transitionAppointment(targetStatus: AppointmentAttemptStatus) {
    const appointmentId = visitCase?.currentAppointment?.appointmentId;
    if (!appointmentId) return;

    let reason: string | undefined;
    if (targetStatus === "REJECTED" || targetStatus === "CANCELLED") {
      reason = window.prompt("Motif (requis) ?")?.trim();
      if (!reason) return;
    }

    let proposedStartsAt: string | undefined;
    if (targetStatus === "RESCHEDULE_PROPOSED") {
      const value = window.prompt("Nouveau créneau souhaité (AAAA-MM-JJ HH:MM) ?");
      if (!value) return;
      proposedStartsAt = new Date(value).toISOString();
    }

    setError(null);
    setBusy(true);
    try {
      await finalVisitsApi.transitionAppointment(appointmentId, {
        targetStatus,
        reason,
        proposedStartsAt,
      });
