      console.error("[FinalVisitPanel] transitionAppointment failed", err);
    } finally {
      setBusy(false);
    }
  }

  function addDraftSnag() {
    setDraftSnags((prev) => [...prev, { description: "", severity: "MINOR" }]);
  }

  function updateDraftSnag(index: number, patch: Partial<SnagInput>) {
    setDraftSnags((prev) => prev.map((s, i) => (i === index ? { ...s, ...patch } : s)));
  }

  function removeDraftSnag(index: number) {
    setDraftSnags((prev) => prev.filter((_, i) => i !== index));
  }

  async function submitReport(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = new FormData(e.currentTarget);
    const appointmentId = visitCase?.currentAppointment?.appointmentId;

