  async function transitionAppointment(targetStatus: AppointmentAttemptStatus) {
    const appointmentId = visitCase?.currentAppointment?.appointmentId;
    if (!appointmentId) return;

    let reason: string | undefined;
    if (targetStatus === "REJECTED" || targetStatus === "CANCELLED") {
