      // early-completion guard: a visit cannot be marked Completed before
      // its start time). Falling through to String(err) instead of the
      // generic fallback, and logging to the console, so a shape of error
      // this branch doesn't expect still surfaces something instead of
      // nothing.
      const message =
        err instanceof ApiError
          ? err.message
          : err instanceof Error
          ? err.message
          : "Échec de la mise à jour du rendez-vous.";
      setError(message);
      // eslint-disable-next-line no-console
