  async submitReport(
    appointmentId: string,
    data: {
      resultCode: VisitResult;
      generalCondition?: string;
      observations?: string;
      authorUserId?: string;
      snags: SnagInput[];
    }
  ): Promise<{ reportId: string; versionNo: number; status: string; snagCount: number; message: string }> {
    return projectFetch(`/api/final-visits/appointments/${appointmentId}/report`, {
      method: "POST",
      body: JSON.stringify({
        ...data,
        resultCode: visitResultCode.toInt(data.resultCode),
        snags: data.snags.map((s) => ({ ...s, severity: snagSeverityCode.toInt(s.severity) })),
      }),
