import { expect, test } from "@playwright/test";
import { Api, expectRefused, orNull } from "./support/api";
import * as st from "./support/state";
import { promptAnswers } from "./support/ui";

/**
 * Scope 5 — Visite finale.
 * Wire values: appointment 0 REQUESTED, 1 CONFIRMED, 2 RESCHEDULE_PROPOSED, 4 CANCELLED, 5 COMPLETED, 6 NO_SHOW;
 * visit result 0 COMPLIANT_NO_SNAG … 2 NON_COMPLIANT_MAJOR_SNAGS; eligibility 0 ELIGIBLE, 4 NOT_ELIGIBLE_FINAL_VISIT_PENDING.
 */
const APPT = st.AppointmentStatus;

interface CaseDto {
  responsibleSalesAgentId?: string;
  responsibleSalesAgentName?: string;
  currentAppointment?: { appointmentId: string; attemptNo: number; startsAt: string; status: number; causeType?: string } | null;
  currentReport?: {
    resultCode: number;
    generalCondition?: string;
    observations?: string;
    clientFeedback?: string;
    nonComplianceReason?: string;
    correctiveAction?: string;
    followUpNotes?: string;
    snags: { description: string; severity: number }[];
  } | null;
}

async function visitCase(reservationId: string) {
  const agent = await Api.as("agent");
  return agent.get<CaseDto>(`/api/final-visits/reservations/${reservationId}/case`);
}

const local = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")} ${String(d.getHours()).padStart(2, "0")}:00`;

test.describe("Acheteur", { tag: "@buyer" }, () => {
  test("final_visit_requestable_only_after_reservation_approved", async ({ page }) => {
    const p = await st.createProject();
    const submitted = await st.createReservation(p, { state: "SUBMITTED", unitIndex: 0 });
    const approved = await st.createReservation(p, { state: "APPROVED", unitIndex: 1 });
    await st.setConstructionPct(p, 100);
    await st.completeProject(p);
    const buyer = await Api.as("buyer", true);

    // Not approved: no request action, and the API refuses.
    await page.goto(`/my/properties/${submitted.reservationId}`);
    await expect(page.getByRole("heading", { level: 1 })).toBeVisible();
    await expect(page.getByRole("button", { name: "Demander une visite" })).toHaveCount(0);
    await expectRefused(
      await buyer.raw("POST", `/api/final-visits/reservations/${submitted.reservationId}/request`, { reservationId: submitted.reservationId, startsAt: "2027-02-01T10:00:00" }),
      [409],
      "final visit on a submitted reservation",
    );

    // Approved: the buyer can request it.
    const answer = promptAnswers(page);
    answer.next = local(new Date(Date.now() + 12 * 86400000));
    await page.goto(`/my/properties/${approved.reservationId}`);
    await page.getByRole("button", { name: "Demander une visite" }).click();
    await expect.poll(orNull(async () => (await visitCase(approved.reservationId)).currentAppointment?.status ?? null)).toBe(APPT.Requested);
    await expect(page.getByRole("alert")).toHaveCount(0);
  });

  test("buyer_can_view_own_visits_but_cannot_edit_feedback", async ({ page }) => {
    const j = await st.approvedInDelivery();
    await st.createFinalVisit(j, "COMPLIANT", { report: { clientFeedback: "Très satisfait de la finition (E2E)", followUpNotes: "Remise des clés à planifier (E2E)" } });

    await page.goto(`/my/properties/${j.reservationId}`);
    const card = page.locator(".card").filter({ has: page.getByRole("heading", { name: "Compte-rendu de visite finale" }) });
    await expect(card.getByText("Très satisfait de la finition (E2E)")).toBeVisible();
    await expect(card.getByText("Remise des clés à planifier (E2E)")).toBeVisible();
    // Read-only: nothing to type into, no report authoring.
    await expect(card.locator("input, textarea, select")).toHaveCount(0);
    await expect(page.getByRole("button", { name: "Saisir un rapport de visite" })).toHaveCount(0);

    const buyer = await Api.as("buyer", true);
    await expectRefused(
      await buyer.raw("POST", `/api/final-visits/appointments/${j.finalVisitAppointmentId}/report`, {
        appointmentId: j.finalVisitAppointmentId, resultCode: 0, clientFeedback: "modifié par l'acheteur", snags: [],
      }),
      [403],
      "buyer authors a report",
    );
    await expectRefused(await buyer.raw("GET", `/api/final-visits/reservations/${j.reservationId}/case`), [403], "buyer reads the internal case");
    expect((await visitCase(j.reservationId)).currentReport?.clientFeedback).toBe("Très satisfait de la finition (E2E)");
  });
});

test.describe("Agent", { tag: "@agent" }, () => {
  test("final_visit_form_persists_all_fields", async ({ page }) => {
    const j = await st.approvedInDelivery();
    await st.createFinalVisit(j, "REQUESTED", { pastStart: true });
    const requested = await visitCase(j.reservationId);

    await page.goto(`/admin/units/${j.unitId}`);
    await page.getByRole("button", { name: "Confirmer", exact: true }).click();
    await page.getByRole("button", { name: "Marquer réalisée" }).click();
    await page.getByRole("button", { name: "Saisir un rapport de visite" }).click();
    await page.getByLabel("État général").fill("Peinture à reprendre");
    await page.getByLabel("Observations (remarques)").fill("Fissure dans la salle de bain");
    await page.getByLabel("Feedback du client").fill("Client déçu par la salle de bain");
    await page.getByLabel("Suivi").fill("Contre-visite dans 15 jours");
    await page.getByRole("button", { name: "+ Ajouter une réserve" }).click();
    await page.getByPlaceholder("Description de la réserve").fill("Fissure carrelage");
    await page.locator("form select").last().selectOption("MAJOR");
    await page.getByLabel("Motif (visite non satisfaisante)").fill("Défaut de carrelage");
    await page.getByLabel("Action corrective").fill("Remplacement du carrelage par l'entreprise");
    await page.getByRole("button", { name: "Envoyer le rapport" }).click();
    await expect(page.getByRole("alert")).toHaveCount(0);

    await expect.poll(orNull(async () => (await visitCase(j.reservationId)).currentReport?.correctiveAction ?? null)).not.toBeNull();
    const c = await visitCase(j.reservationId);
    const agent = await Api.as("agent");
    expect(c.currentAppointment?.startsAt).toBe(requested.currentAppointment?.startsAt); // date et heure
    expect(c.responsibleSalesAgentId).toBe(agent.userId); // agent commercial
    expect(c.responsibleSalesAgentName).toBeTruthy();
    expect(c.currentAppointment?.status).toBe(APPT.Completed); // statut
    expect(c.currentReport?.resultCode).toBe(2); // résultat : non satisfaisante (réserve majeure)
    expect(c.currentReport?.clientFeedback).toBe("Client déçu par la salle de bain"); // feedback
    expect(c.currentReport?.nonComplianceReason).toBe("Défaut de carrelage"); // motif
    expect(c.currentReport?.observations).toBe("Fissure dans la salle de bain"); // remarques
    expect(c.currentReport?.followUpNotes).toBe("Contre-visite dans 15 jours"); // suivi
    expect(c.currentReport?.correctiveAction).toBe("Remplacement du carrelage par l'entreprise");
    expect(c.currentReport?.snags.map((s) => s.description)).toEqual(["Fissure carrelage"]);

    // Re-read after reload in the UI.
    await page.reload();
    for (const text of ["Client déçu par la salle de bain", "Défaut de carrelage", "Contre-visite dans 15 jours", "Remplacement du carrelage par l'entreprise"]) {
      await expect(page.getByText(text).first()).toBeVisible();
    }
  });

  test("visit_satisfactory_makes_file_eligible_for_notary", async ({ page }) => {
    const j = await st.approvedInDelivery();
    const agent = await Api.as("agent");
    const eligibility = async () =>
      agent.get<{ status: number; canRequestAppointment: boolean }>(`/api/final-visits/reservations/${j.reservationId}/notary-eligibility`);
    expect((await eligibility()).status).toBe(4); // visite finale en attente
    expect((await eligibility()).canRequestAppointment).toBe(false);

    await st.createFinalVisit(j, "COMPLIANT"); // client present, compliant report acknowledged, title available
    const after = await eligibility();
    expect(after.status).toBe(0);
    expect(after.canRequestAppointment).toBe(true);

    await page.goto(`/admin/units/${j.unitId}`);
    await expect(page.getByText("Éligible", { exact: true }).first()).toBeVisible();
    // Eligibility is what unlocks the notary appointment: the agent can now book it.
    await st.createNotaryAppointment(j);
    expect(j.notaryAppointmentId).toBeTruthy();
  });

  test("visit_unsatisfactory_requires_reason_and_corrective_action", async ({ page }) => {
    const j = await st.approvedInDelivery();
    const appointmentId = await st.completedVisitWithoutReport(j);
    const agent = await Api.as("agent");

    // API: a non-compliant report missing either field is refused, field by field.
    const res = await agent.raw("POST", `/api/final-visits/appointments/${appointmentId}/report`, {
      appointmentId, resultCode: 2, snags: [{ description: "Porte cassée", severity: 1 }],
    });
    expect(res.status()).toBe(422);
    const body = await res.json();
    expect(Object.keys(body.errors ?? {})).toEqual(expect.arrayContaining(["NonComplianceReason", "CorrectiveAction"]));
    const onlyReason = await agent.raw("POST", `/api/final-visits/appointments/${appointmentId}/report`, {
      appointmentId, resultCode: 2, nonComplianceReason: "Porte cassée", snags: [{ description: "Porte cassée", severity: 1 }],
    });
    expect(onlyReason.status()).toBe(422);
    expect((await visitCase(j.reservationId)).currentReport ?? null).toBeNull();

    // UI: the two fields appear as soon as a major reserve is added and are required.
    await page.goto(`/admin/units/${j.unitId}`);
    await page.getByRole("button", { name: "Saisir un rapport de visite" }).click();
    await expect(page.getByLabel("Motif (visite non satisfaisante)")).toHaveCount(0);
    await page.getByRole("button", { name: "+ Ajouter une réserve" }).click();
    await page.getByPlaceholder("Description de la réserve").fill("Porte cassée");
    await page.locator("form select").last().selectOption("MAJOR");
    await expect(page.getByText("Non satisfaisante (réserve majeure ou bloquante)")).toBeVisible();
    await page.getByRole("button", { name: "Envoyer le rapport" }).click();
    await expect(page.getByLabel("Motif (visite non satisfaisante)")).toHaveJSProperty("validity.valueMissing", true);
    expect((await visitCase(j.reservationId)).currentReport ?? null).toBeNull();

    await page.getByLabel("Motif (visite non satisfaisante)").fill("Porte d'entrée cassée");
    await page.getByLabel("Action corrective").fill("Remplacement de la porte");
    await page.getByRole("button", { name: "Envoyer le rapport" }).click();
    await expect.poll(orNull(async () => (await visitCase(j.reservationId)).currentReport?.nonComplianceReason ?? null)).toBe("Porte d'entrée cassée");
  });

  test("visit_client_absent_allows_cancel_or_reschedule", async ({ page }) => {
    const answer = promptAnswers(page);
    const toReschedule = await st.approvedInDelivery();
    const toCancel = await st.approvedInDelivery();
    const agent = await Api.as("agent");
    for (const j of [toReschedule, toCancel]) {
      await st.createFinalVisit(j, "REQUESTED", { pastStart: true });
      await agent.post(`/api/final-visits/appointments/${j.finalVisitAppointmentId}/transition`, { appointmentId: j.finalVisitAppointmentId, targetStatus: APPT.Confirmed });
    }

    // Client absent → reschedule: a new attempt at the new date.
    await page.goto(`/admin/units/${toReschedule.unitId}`);
    await page.getByRole("button", { name: "Acheteur absent" }).click();
    await expect(page.getByRole("button", { name: "Reprogrammer la visite" })).toBeVisible();
    await expect(page.getByRole("button", { name: "Annuler la visite" })).toBeVisible();
    const newDate = new Date(Date.now() + 20 * 86400000);
    newDate.setHours(10, 0, 0, 0);
    answer.next = local(newDate);
    await page.getByRole("button", { name: "Reprogrammer la visite" }).click();
    await expect.poll(orNull(async () => (await visitCase(toReschedule.reservationId)).currentAppointment?.attemptNo ?? null)).toBe(2);
    const rescheduled = (await visitCase(toReschedule.reservationId)).currentAppointment!;
    expect(rescheduled.status).toBe(APPT.Requested);
    expect(rescheduled.causeType).toBe("NO_SHOW");
    expect(new Date(`${rescheduled.startsAt}Z`).getTime() - newDate.getTime()).toBeLessThan(24 * 3600 * 1000);

    // Client absent → cancel (with a reason).
    await page.goto(`/admin/units/${toCancel.unitId}`);
    await page.getByRole("button", { name: "Acheteur absent" }).click();
    answer.next = "Client injoignable (E2E)";
    await page.getByRole("button", { name: "Annuler la visite" }).click();
    await expect.poll(orNull(async () => (await visitCase(toCancel.reservationId)).currentAppointment?.status ?? null)).toBe(APPT.Cancelled);
  });

  test("visit_rescheduled_requires_new_date", async ({ page }) => {
    const answer = promptAnswers(page);
    const j = await st.approvedInDelivery();
    await st.createFinalVisit(j, "REQUESTED", { pastStart: false });
    const agent = await Api.as("agent");
    const before = (await visitCase(j.reservationId)).currentAppointment!;

    await expectRefused(
      await agent.raw("POST", `/api/final-visits/appointments/${before.appointmentId}/transition`, { appointmentId: before.appointmentId, targetStatus: APPT.RescheduleProposed }),
      [422],
      "reschedule without a date",
    );
    expect((await visitCase(j.reservationId)).currentAppointment?.status).toBe(APPT.Requested);

    await page.goto(`/admin/units/${j.unitId}`);
    answer.next = null; // agent dismisses the date prompt → nothing happens
    await page.getByRole("button", { name: "Proposer un autre créneau" }).click();
    await expect(page.getByRole("button", { name: "Proposer un autre créneau" })).toBeVisible();
    expect((await visitCase(j.reservationId)).currentAppointment?.status).toBe(APPT.Requested);

    const newDate = new Date(Date.now() + 30 * 86400000);
    newDate.setHours(15, 0, 0, 0);
    answer.next = local(newDate);
    await page.getByRole("button", { name: "Proposer un autre créneau" }).click();
    await expect.poll(orNull(async () => (await visitCase(j.reservationId)).currentAppointment?.status ?? null)).toBe(APPT.RescheduleProposed);
    const after = (await visitCase(j.reservationId)).currentAppointment!;
    expect(after.startsAt).not.toBe(before.startsAt);
  });

  test("agent_can_manage_visit_and_enter_feedback", async ({ page }) => {
    const j = await st.approvedInDelivery();
    await st.createFinalVisit(j, "REQUESTED", { pastStart: true });

    await page.goto(`/admin/units/${j.unitId}`);
    await expect(page.getByText("Agent commercial :")).toBeVisible();
    await page.getByRole("button", { name: "Confirmer", exact: true }).click();
    await expect.poll(orNull(async () => (await visitCase(j.reservationId)).currentAppointment?.status ?? null)).toBe(APPT.Confirmed);
    await page.getByRole("button", { name: "Marquer réalisée" }).click();
    await expect.poll(orNull(async () => (await visitCase(j.reservationId)).currentAppointment?.status ?? null)).toBe(APPT.Completed);
    await page.getByRole("button", { name: "Saisir un rapport de visite" }).click();
    await page.getByLabel("Feedback du client").fill("Le client apprécie la luminosité (E2E)");
    await page.getByRole("button", { name: "Envoyer le rapport" }).click();

    await expect.poll(orNull(async () => (await visitCase(j.reservationId)).currentReport?.clientFeedback ?? null)).toBe("Le client apprécie la luminosité (E2E)");
    expect((await visitCase(j.reservationId)).currentReport?.resultCode).toBe(0);
    await page.reload();
    await expect(page.getByText("Le client apprécie la luminosité (E2E)")).toBeVisible();
  });
});

