 *
 * Opening a sale is gated server-side on five preconditions (reservation
 * APPROVED, project in delivery, final visit cleared, no active sale already,
 * caller in the project perimeter). This panel does NOT re-implement them: the
 * only thing it knows locally is the reservation's own status, which is what
 * decides whether offering the action makes sense at all. Everything else comes
 * back as a typed 409/422 and is shown verbatim — a second copy of the rules
 * here would drift from the ones actually enforced, and would be wrong in the
 * direction that matters (showing the action as available when it is not).
 *
 * Nothing here can confirm a sale. Confirmed is written by exactly one thing,
  const canOfferCreate = canManage && reservationStatus === "APPROVED" && !isActive(sale);

  return (
    <Card>
      <div className="page-header" style={{ marginBottom: 12 }}>
        <h4 style={{ margin: 0 }}>Vente</h4>
        {canOfferCreate && (
          <Button onClick={() => setCreateOpen(true)} disabled={busy}>
            Créer une vente
          </Button>
        )}
      </div>

      {error && <p className="form-error">{error}</p>}

      {!sale && (
        <p className="muted small">
          {canOfferCreate
            ? "Aucune vente ouverte. La création exige un projet en livraison et une visite finale levée — " +
              "le serveur en indiquera le motif si une condition manque."
            : "Aucune vente ouverte pour cette réservation."}
        </p>
      )}

      {sale && (
        <>
          <dl className="detail-list">
            <dt>Statut</dt>
            <dd>
              <StatusBadge status={sale.status} label={SALE_STATUS_LABEL[sale.status]} />
            </dd>
            <dt>Acquéreur</dt>
            <dd>
              {sale.buyerFirstName} {sale.buyerLastName}
            </dd>
            <dt>Date de vente</dt>
            <dd>{formatDate(sale.saleDate)}</dd>
            <dt>Prix convenu</dt>
            <dd>{formatMAD(sale.finalPrice ?? sale.totalPrice)}</dd>
            {sale.reservationAmount != null && (
              <>
                <dt>Acompte réservation</dt>
                <dd>{formatMAD(sale.reservationAmount)}</dd>
              </>
            )}
            {sale.remainingAmount != null && (
              <>
                <dt>Solde à régler</dt>
                <dd>{formatMAD(sale.remainingAmount)}</dd>
              </>
            )}
            <dt>Garantie</dt>
            <dd>{sale.warrantyMonths} mois</dd>
            {sale.confirmedAt && (
              <>
                <dt>Confirmée le</dt>
                <dd>{formatDateTime(sale.confirmedAt)}</dd>
              </>
            )}
            {sale.notes && (
              <>
                <dt>Notes</dt>
                <dd style={{ whiteSpace: "pre-line" }}>{sale.notes}</dd>
              </>
            )}
          </dl>

          {/* isEditable comes from the API's own state machine — never recomputed
              from the status string here. */}
          {canManage && sale.isEditable && (
            <div className="modal-actions" style={{ marginTop: 12 }}>
              <Button variant="ghost" onClick={() => setEditOpen(true)} disabled={busy}>
                Modifier
              </Button>
              <Button variant="danger" onClick={cancel} disabled={busy}>
                Annuler la vente
              </Button>
            </div>
          )}

          {sale.status === "Confirmed" && (
            <p className="muted small" style={{ marginTop: 10 }}>
              Vente finalisée chez le notaire — elle n'est plus modifiable (§5.7).
            </p>
          )}
        </>
      )}

      {createOpen && (
        <Modal
          title="Créer une vente"
          onClose={() => {
            if (!busy) setCreateOpen(false);
          }}
        >
          <form onSubmit={create}>
            <p className="muted small">
              L'acquéreur, le bien, l'acompte et la durée de garantie sont repris de la réservation et du
              projet — ils ne se saisissent pas ici.
            </p>
            <Field label="Date de vente">
import type { AdminSalesPage, Sale, UserSalesSummary } from "../../types";
import type { SalesApi } from "../interfaces";
import { buildQuery, projectFetch } from "./client";

interface SaleItemDto {
  saleId: string;
  unitId: string;
  saleDate: string;
  totalPrice: number;
  paid: number;
  remaining: number;
}

interface UserSalesResponseDto {
  sales: SaleItemDto[];
  totalPrice: number;
  totalPaid: number;
  totalRemaining: number;
}

export const salesApi: SalesApi = {
  async listAll(params) {
    return projectFetch<AdminSalesPage>(
      `/api/sales${buildQuery({
        PageNumber: params?.pageNumber ?? 1,
        PageSize: params?.pageSize ?? 100,
        Search: params?.search || undefined,
        ProjectId: params?.projectId || undefined,
      })}`
    );
  },

  async getByUser(userId) {
    const dto = await projectFetch<UserSalesResponseDto>(`/api/sales/user/${userId}`);
    const summary: UserSalesSummary = {
      totalPrice: dto.totalPrice,
      totalPaid: dto.totalPaid,
      totalRemaining: dto.totalRemaining,
      // Backend doesn't return projectName/unitDetails/payments on this endpoint —
      // joining against Immeuble/Unit data would need extra calls, left blank for now.
      sales: dto.sales.map((s) => ({
        saleId: s.saleId,
        unitId: s.unitId,
        projectName: "",
        unitDetails: "",
        price: s.totalPrice,
        totalPaid: s.paid,
        remaining: s.remaining,
        saleDate: s.saleDate,
        payments: [],
      })),
    };
    return summary;
  },

  // §5.7/§6 — the sale draft flow. The backend derives the buyer, the unit and
  // the deposit from the reservation, so none of them are sent from here.
  async createDraft(body) {
    return projectFetch<Sale>("/api/sales", {
      method: "POST",
      body: JSON.stringify(body),
    });
  },

  async getByReservation(reservationId) {
    // 200 with a null body is the normal "no sale yet" answer, not an error.
    const sale = await projectFetch<Sale | null>(`/api/sales/by-reservation/${reservationId}`);
    return sale ?? null;
  },

  async updateDraft(saleId, body) {
    return projectFetch<Sale>(`/api/sales/${saleId}`, {
      method: "PUT",
      body: JSON.stringify(body),
    });
  },

  async cancelDraft(saleId, reason) {
    return projectFetch<Sale>(`/api/sales/${saleId}/cancel`, {
      method: "POST",
      body: JSON.stringify({ reason }),
    });
  },
};
