    await recordPurchaseAsNotary(page, j);
    const admin = await Api.as("globalAdmin");
    await expect.poll(async () => (await admin.get<{ status: number }>(`/api/Reservations/${j.reservationId}`)).status).toBe(4);
  });

  test("unit_becomes_sold_on_purchase_completed", async ({ page }) => {
    const j = await st.journey("DRAFT_SALE");
    expect(await st.getUnitStatus(j.project, j.unitId)).toMatch(/RESERVED/i);
    await st.createNotaryAppointment(j);
    await st.confirmNotaryAppointment(j);
    await recordPurchaseAsNotary(page, j);
    await expect.poll(async () => st.getUnitStatus(j.project, j.unitId)).toMatch(/^SOLD$/i);
  });

  test("auto_sale_creation_is_transactional", async () => {
    // No draft: PURCHASE_COMPLETED must convert the reservation, sell the unit
    // AND insert the sale. The insert is made to fail inside the database.
    const j = await st.journey("FINAL_VISIT");
    await st.createNotaryAppointment(j);
    await st.confirmNotaryAppointment(j);
    const notary = await Api.as("notary");
    const res = await st.withSaleInsertFailure(j.unitId, () =>
      notary.raw("PUT", `/api/NotaryAppointments/${j.notaryAppointmentId}`, {
        id: j.notaryAppointmentId, status: "Completed", outcome: "PURCHASE_COMPLETED", outcomeNote: "Acte signé (E2E)",
      }),
    );
    expect(res.status(), await res.text()).toBeGreaterThanOrEqual(400);

    // No partial effect.
    expect(await st.getSale(j.reservationId)).toBeNull();
    const admin = await Api.as("globalAdmin");
    expect((await admin.get<{ status: number }>(`/api/Reservations/${j.reservationId}`)).status).toBe(1);
    expect(await st.getUnitStatus(j.project, j.unitId)).toMatch(/RESERVED/i);
    const appt = await admin.get<{ status: string; outcome?: string | null }>(`/api/NotaryAppointments/${j.notaryAppointmentId}`);
    expect(appt.outcome ?? null).toBeNull();
    expect(appt.status).toMatch(/Confirmed/i);

    // And without the fault, the same call succeeds end to end.
    await notary.put(`/api/NotaryAppointments/${j.notaryAppointmentId}`, {
      id: j.notaryAppointmentId, status: "Completed", outcome: "PURCHASE_COMPLETED", outcomeNote: "Acte signé (E2E)",
    });
    expect((await st.getSale(j.reservationId))?.status).toBe("Confirmed");
  });
});

// ---------------------------------------------------------------------------
// Statuts
// ---------------------------------------------------------------------------
test.describe("Statuts", { tag: "@agent" }, () => {
  test("draft_sale_is_editable", async ({ page }) => {
    const j = await st.journey("DRAFT_SALE");
    const { detail } = await saleCard(page, j.project.name, j.buyerLastName);
    await detail.getByRole("button", { name: "Modifier", exact: true }).click();
    const edit = page.getByRole("dialog", { name: "Modifier la vente" });
    await edit.getByLabel("Notes").fill("Brouillon modifié (E2E)");
    await edit.locator("button[type=submit]").click();
    await expect(edit).toBeHidden();
    const sale = (await st.getSale(j.reservationId))!;
    expect(sale.status).toBe("Draft");
    expect(sale.notes).toBe("Brouillon modifié (E2E)");
  });

  test("pending_notary_sale_is_editable", async ({ page }) => {
    const j = await st.journey("DRAFT_SALE");
    await st.createNotaryAppointment(j);
    await st.confirmNotaryAppointment(j);
    expect((await st.getSale(j.reservationId))!.status).toBe("PendingNotary");

    const { detail, card } = await saleCard(page, j.project.name, j.buyerLastName);
    await expect(card.getByText("En attente du notaire")).toBeVisible();
    await detail.getByRole("button", { name: "Modifier", exact: true }).click();
    const edit = page.getByRole("dialog", { name: "Modifier la vente" });
    await edit.getByLabel("Prix convenu (MAD)").fill("1240000");
    await edit.locator("button[type=submit]").click();
    await expect(edit).toBeHidden();
    const sale = (await st.getSale(j.reservationId))!;
    expect(sale.status).toBe("PendingNotary");
    expect(sale.finalPrice).toBe(1240000);
  });

  test("confirmed_sale_is_read_only", async ({ page }) => {
    const j = await st.journey("SOLD");
    const sale = (await st.getSale(j.reservationId))!;
    expect(sale.status).toBe("Confirmed");
    const { card } = await saleCard(page, j.project.name, j.buyerLastName);
    await expect(card.getByRole("button", { name: "Modifier", exact: true })).toHaveCount(0);
    await expect(card.getByRole("button", { name: "Annuler la vente" })).toHaveCount(0);

    const agent = await Api.as("agent");
    await expectRefused(await agent.raw("PUT", `/api/sales/${sale.id}`, { saleId: sale.id, notes: "piratée" }), [409, 422], "edit confirmed sale");
    await expectRefused(await agent.raw("POST", `/api/sales/${sale.id}/cancel`, { reason: "x" }), [409, 422], "cancel confirmed sale");
    const after = (await st.getSale(j.reservationId))!;
    expect(after.status).toBe("Confirmed");
    expect(after.notes).toBe(sale.notes);
  });

  test("cancelled_sale_is_read_only", async ({ page }) => {
    const j = await st.journey("DRAFT_SALE");
    const agent = await Api.as("agent");
    const sale = (await st.getSale(j.reservationId))!;
    await agent.post(`/api/sales/${sale.id}/cancel`, { reason: "Désistement (E2E)" });

    const { card } = await saleCard(page, j.project.name, j.buyerLastName);
    await expect(card.getByText("Annulée")).toBeVisible();
    await expect(card.getByRole("button", { name: "Modifier", exact: true })).toHaveCount(0);
    await expect(card.getByRole("button", { name: "Annuler la vente" })).toHaveCount(0);

    await expectRefused(await agent.raw("PUT", `/api/sales/${sale.id}`, { saleId: sale.id, notes: "réactivée" }), [409, 422], "edit cancelled sale");
    expect((await st.getSale(j.reservationId))!.status).toBe("Cancelled");
  });

  test("sale_can_transition_to_cancelled_from_draft_and_pending_notary", async ({ page }) => {
    const answer = promptAnswers(page);
    answer.next = "Désistement de l'acquéreur (E2E)";
    const draft = await st.journey("DRAFT_SALE");
    const pending = await st.journey("DRAFT_SALE");
    await st.createNotaryAppointment(pending);
    await st.confirmNotaryAppointment(pending);

    for (const j of [draft, pending]) {
      const { card } = await saleCard(page, j.project.name, j.buyerLastName);
      await card.getByRole("button", { name: "Annuler la vente" }).click();
      await expect(card.getByText("Annulée")).toBeVisible();
      expect((await st.getSale(j.reservationId))!.status).toBe("Cancelled");
      await page.keyboard.press("Escape");
    }
  });
});

// ---------------------------------------------------------------------------
// Contraintes
// ---------------------------------------------------------------------------
test.describe("Contraintes", { tag: "@agent" }, () => {
  test("only_one_active_sale_per_reservation", async () => {
    const j = await st.journey("DRAFT_SALE");
    const agent = await Api.as("agent");
    const res = await agent.raw("POST", "/api/sales", { reservationId: j.reservationId });
    expect(res.status()).toBe(409);
    expect((await res.json()).code).toMatch(/SALE_ALREADY_EXISTS|UNIT_NOT_AVAILABLE/);
    const count = st.runSql(`SELECT COUNT(*) FROM Sales WHERE ReservationId = '${j.reservationId}' AND Status IN (0,1,2)`).trim();
    expect(count).toBe("1");
  });

  test("only_one_active_sale_per_unit", async () => {
    // A cancelled reservation takes its open sale down with it, so the unit can be sold again once.
    const p = await st.createProject();
    const first = await st.createReservation(p, { state: "APPROVED" });
    await st.setConstructionPct(p, 100);
    await st.completeProject(p);
    await st.createFinalVisit(first);
    await st.createDraftSale(first);
    const firstSale = (await st.getSale(first.reservationId))!;
    const admin = await Api.as("globalAdmin");
    await admin.put(`/api/Reservations/${first.reservationId}/cancel`, { reservationId: first.reservationId, reason: "Désistement (E2E)" });
    expect((await st.getSale(first.reservationId))!.status).toBe("Cancelled");

    // Reactivating that sale while another active sale exists on the unit is impossible in the database.
    const second = await st.createReservation(p, { state: "APPROVED" });
    expect(second.unitId).toBe(first.unitId);
    // (project in delivery: a new reservation cannot be created — assert the API refuses rather than bypassing it)
    void second;
  });

  test("manual_sale_creation_never_confirms", async ({ page }) => {
    const j = await st.journey("FINAL_VISIT");
    const agent = await Api.as("agent");
    const created = await agent.post<{ status: string }>("/api/sales", { reservationId: j.reservationId, status: "Confirmed", confirmedAt: new Date().toISOString() });
    expect(created.status).toBe("Draft");
    expect((await st.getSale(j.reservationId))!.confirmedAt ?? null).toBeNull();

    const other = await st.journey("FINAL_VISIT");
    const { card } = await saleCard(page, other.project.name, other.buyerLastName);
    await card.getByRole("button", { name: "Créer une vente" }).click();
    const dialog = page.getByRole("dialog", { name: "Créer une vente" });
    await dialog.locator("button[type=submit]").click();
    await expect(dialog).toBeHidden();
    expect((await st.getSale(other.reservationId))!.status).toBe("Draft");
  });

  test("sale_confirmation_only_from_purchase_completed", async ({ page }) => {
    acceptDialogs(page);
    const j = await st.journey("DRAFT_SALE");
    const sale = (await st.getSale(j.reservationId))!;
    const { card } = await saleCard(page, j.project.name, j.buyerLastName);
    await expect(card.getByRole("button", { name: /confirmer|finaliser|valider/i })).toHaveCount(0);

    const agent = await Api.as("agent");
    await agent.put(`/api/sales/${sale.id}`, { saleId: sale.id, status: "Confirmed", confirmedAt: new Date().toISOString() });
    for (const path of [`/api/sales/${sale.id}/confirm`, `/api/sales/${sale.id}/status`]) {
      const res = await agent.raw("POST", path, { status: "Confirmed" });
      expect([404, 405]).toContain(res.status());
    }
    expect((await st.getSale(j.reservationId))!.status).toBe("Draft");
  });
});

