  async listAppointments(query) {
    const qs = buildQuery({
      Status: query?.status
        ? notaryAppointmentStatus.toLegacy(query.status as NotaryAppointment["status"])
        : undefined,
      PageNumber: query?.pageNumber,
      PageSize: query?.pageSize,
    });
