import { expect, test, type Page } from "@playwright/test";
import { Api, expectRefused, orNull } from "./support/api";
import * as st from "./support/state";
import { promptAnswers } from "./support/ui";

/** Scope 7 — Rendez-vous notaire. */

interface NotaryDto {
  id: string;
  reservationId: string;
  notaireId?: string;
  appointmentDate: string;
  status: string;
  outcome?: string | null;
  outcomeNote?: string | null;
  taxFees: number;
  tahfidFees: number;
}

async function appointment(id: string) {
  const admin = await Api.as("globalAdmin");
  return admin.get<NotaryDto>(`/api/NotaryAppointments/${id}`);
}

async function appointmentsOf(reservationId: string) {
  const admin = await Api.as("globalAdmin");
  return (await admin.all<NotaryDto>("/api/NotaryAppointments")).filter((a) => a.reservationId === reservationId);
}

const localInput = (d: Date) => new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 16);

async function confirmFromList(page: Page, buyerLastName: string) {
  await page.goto("/admin/notary-appointments");
  const row = page.getByRole("row").filter({ hasText: buyerLastName });
  await expect(row).toHaveCount(1);
  await row.getByRole("button", { name: "Confirmer" }).click();
}

test.describe("Acheteur", { tag: "@buyer" }, () => {
  test("buyer_appointment_request_created_with_status_requested", async ({ page }) => {
    const j = await st.journey("FINAL_VISIT");
    await page.goto(`/my/properties/${j.reservationId}`);
    await page.getByRole("button", { name: "Demander un RDV notaire" }).click();
    const when = new Date(Date.now() + (40 + Math.floor(Math.random() * 300)) * 86400000);
    when.setHours(14, 0, 0, 0);
    await page.getByLabel("Date et heure souhaitées").fill(localInput(when));
    await page.getByRole("button", { name: "Envoyer la demande" }).click();

    await expect.poll(async () => (await appointmentsOf(j.reservationId)).length).toBe(1);
    const created = (await appointmentsOf(j.reservationId))[0];
    expect(created.status).toMatch(/^Requested$/i);
    const buyer = await Api.as("buyer", true);
    expect((await buyer.get<NotaryDto>(`/api/NotaryAppointments/${created.id}`)).status).toMatch(/^Requested$/i);
    const history = page.locator(".card").filter({ has: page.getByRole("heading", { name: "Rendez-vous notaire", exact: true }) });
    await expect(history.getByRole("row")).toHaveCount(2); // header + the request
  });

  test("buyer_cannot_set_purchase_completed", async ({ page }) => {
    const j = await st.journey("FINAL_VISIT");
    await st.createNotaryAppointment(j);
    await st.confirmNotaryAppointment(j);

    await page.goto(`/my/properties/${j.reservationId}`);
    await expect(page.getByRole("heading", { name: "Rendez-vous notaire", exact: true })).toBeVisible();
    await expect(page.getByRole("button", { name: "Enregistrer le résultat" })).toHaveCount(0);
    await expect(page.getByText("Achat finalisé")).toHaveCount(0);
    await expect(page.getByRole("radio")).toHaveCount(0);

    const buyer = await Api.as("buyer", true);
    await expectRefused(
      await buyer.raw("PUT", `/api/NotaryAppointments/${j.notaryAppointmentId}`, { id: j.notaryAppointmentId, status: "Completed", outcome: "PURCHASE_COMPLETED" }),
      [403],
      "buyer sets PURCHASE_COMPLETED",
    );
    const after = await appointment(j.notaryAppointmentId!);
    expect(after.outcome ?? null).toBeNull();
    expect(after.status).toMatch(/^Confirmed$/i);
    const admin = await Api.as("globalAdmin");
    expect((await admin.get<{ status: number }>(`/api/Reservations/${j.reservationId}`)).status).toBe(1);
  });
});

for (const [tag, label] of [["@agent", "Agent"], ["@projectAdmin", "Admin projet"], ["@notary", "Notaire"]] as const) {
  test.describe(`Confirmation — ${label}`, { tag }, () => {
    test("appointment_confirmable_by_agent_admin_or_notary", async ({ page }) => {
      const j = await st.journey("FINAL_VISIT");
      await st.createNotaryAppointment(j);
      await confirmFromList(page, j.buyerLastName);
      await expect.poll(async () => (await appointment(j.notaryAppointmentId!)).status).toMatch(/^Confirmed$/i);

      if (tag === "@agent") {
        // Not everyone: a technician and the buyer are refused.
        const other = await st.journey("FINAL_VISIT");
        await st.createNotaryAppointment(other);
        for (const key of ["technician", "buyer"] as const) {
          const api = await Api.as(key, true);
          await expectRefused(
            await api.raw("PUT", `/api/NotaryAppointments/${other.notaryAppointmentId}`, { id: other.notaryAppointmentId, status: "Confirmed" }),
            [403],
            `${key} confirms`,
          );
        }
        expect((await appointment(other.notaryAppointmentId!)).status).toMatch(/^Requested$/i);
      }
    });
  });
}

test.describe("Formulaire — agent", { tag: "@agent" }, () => {
  test("appointment_cascade_filters_project_building_floor_unit_reservation", async ({ page }) => {
    const a = await st.createProject({
      layout: { buildings: [{ suffix: "N1", floors: [{ name: "RDC", units: [{}] }] }, { suffix: "N2", floors: [{ name: "ETAGE2", units: [{}, {}] }] }] },
    });
    const a1 = await st.createReservation(a, { state: "APPROVED", unitIndex: 0 });
    const a2 = await st.createReservation(a, { state: "APPROVED", unitIndex: 1 });
    const a3 = await st.createReservation(a, { state: "APPROVED", unitIndex: 2 });
    const b = await st.createProject();
    const b1 = await st.createReservation(b, { state: "APPROVED" });

    await page.goto("/admin/notary-appointments");
    await page.getByRole("button", { name: "Demander un RDV notaire" }).click();
    const dialog = page.getByRole("dialog", { name: "Demander un rendez-vous notarié" });
    const project = dialog.getByLabel("Projet");
    const immeuble = dialog.getByLabel("Immeuble");
    const floor = dialog.getByLabel("Étage");
    const unit = dialog.getByLabel("Unité");
    const dossier = dialog.getByLabel("Dossier (réservation approuvée)");
    const dossierHas = (id: string) => dossier.locator(`option[value="${id}"]`);

    await expect(immeuble).toBeDisabled();
    await expect(dossierHas(b1.reservationId)).toHaveCount(1);

    // Project A: only its buildings and its dossiers.
    await project.selectOption({ label: a.name });
    await expect(immeuble.locator("option").filter({ hasText: "e2e-" })).toHaveText([`${a.name}-N1`, `${a.name}-N2`]);
    for (const r of [a1, a2, a3]) await expect(dossierHas(r.reservationId)).toHaveCount(1);
    await expect(dossierHas(b1.reservationId)).toHaveCount(0);

    // Building N2 → its floor, its two units, their dossiers.
    await immeuble.selectOption({ label: `${a.name}-N2` });
    await expect(floor.locator("option").filter({ hasNotText: /Tous|Choisir/ })).toHaveText(["ETAGE2"]);
    await expect(unit.locator("option").filter({ hasNotText: /Toutes|Choisir/ })).toHaveCount(2);
    await expect(dossierHas(a1.reservationId)).toHaveCount(0);

    // Floor, then unit → exactly one dossier.
    await floor.selectOption("ETAGE2");
    await unit.selectOption(a3.unitId);
    await expect(dossier.locator("option").filter({ hasNotText: "Sélectionner un dossier" })).toHaveCount(1);
    await dossier.selectOption(a3.reservationId);

    // Changing the building resets floor, unit and dossier.
    await immeuble.selectOption({ label: `${a.name}-N1` });
    await expect(floor).toHaveValue("");
    await expect(unit).toHaveValue("");
    await expect(dossier).toHaveValue("");
    await expect(dossierHas(a1.reservationId)).toHaveCount(1);
    await expect(dossierHas(a3.reservationId)).toHaveCount(0);

    // Changing the project resets everything below.
    await project.selectOption({ label: b.name });
    await expect(immeuble).toHaveValue("");
    await expect(dossierHas(b1.reservationId)).toHaveCount(1);
    await expect(dossierHas(a1.reservationId)).toHaveCount(0);
  });

  test("appointment_form_persists_all_fields", async ({ page }) => {
    const j = await st.journey("FINAL_VISIT");
    const notary = await Api.as("notary");
    await page.goto("/admin/notary-appointments");
    await page.getByRole("button", { name: "Demander un RDV notaire" }).click();
    const dialog = page.getByRole("dialog", { name: "Demander un rendez-vous notarié" });
    await dialog.getByLabel("Projet").selectOption({ label: j.project.name });
    await dialog.getByLabel("Dossier (réservation approuvée)").selectOption(j.reservationId);
    await dialog.getByLabel("Notaire affecté").selectOption(notary.userId);
    const when = new Date(Date.now() + (60 + Math.floor(Math.random() * 400)) * 86400000);
    when.setHours(11, 0, 0, 0);
    await dialog.getByLabel("Date et heure").fill(localInput(when));
    await dialog.getByLabel("Frais de taxe (MAD)").fill("31500");
    await dialog.getByLabel("Frais Tahfid (MAD)").fill("9200");
    await dialog.getByRole("button", { name: "Demander le rendez-vous" }).click();
    await expect(dialog).toBeHidden();

    await expect.poll(async () => (await appointmentsOf(j.reservationId)).length).toBe(1);
    const created = await appointment((await appointmentsOf(j.reservationId))[0].id);
    expect(created.notaireId).toBe(notary.userId);
    expect(created.taxFees).toBe(31500);
    expect(created.tahfidFees).toBe(9200);
    expect(new Date(created.appointmentDate.endsWith("Z") ? created.appointmentDate : `${created.appointmentDate}Z`).getTime()).toBe(when.getTime());
  });
});

