open(os.path.join(ROOT, r'Common\Units\UnitLocation.cs'), 'w', encoding='utf-8').write('''using Microsoft.EntityFrameworkCore;
using ProjectAPI.Domain.Immeubles.Entities;
using ProjectAPI.Domain.Projects.Entities;
using ProjectAPI.Domain.Reservations.Entities;
using ProjectAPI.Infrastructure.Context;

using UnitEntity = ProjectAPI.Domain.Immeubles.Entities.Unit;

namespace ProjectAPI.Api.Application.Common.Units;

/// <summary>
/// Where a unit sits: projet → immeuble → étage → unité. Returned with every
/// reservation, notary appointment, claim and final-visit case so screens show
/// the location as details instead of a raw unit id.
/// </summary>
public interface IHasUnitLocation
{
    Guid? ProjectId { get; set; }
    string? ProjectName { get; set; }
    Guid? ImmeubleId { get; set; }
    string? ImmeubleName { get; set; }
    string? FloorName { get; set; }
    string? UnitNumber { get; set; }
}

public sealed record UnitLocation(Guid ProjectId, string ProjectName, Guid ImmeubleId, string ImmeubleName, string? FloorName, string UnitNumber);

public static class UnitLocations
{
    /// <summary>One query for any number of units (Unit.ProjectId references the building).</summary>
    public static async Task<Dictionary<Guid, UnitLocation>> ForUnitsAsync(ApplicationDbContext db, IEnumerable<Guid> unitIds, CancellationToken ct)
    {
        var ids = unitIds.Distinct().ToList();
        if (ids.Count == 0) return new();
        return await (
            from u in db.Set<UnitEntity>()
            join im in db.Set<Immeuble>() on u.ProjectId equals im.Id
            join p in db.Set<Project>() on im.ProjectId equals p.Id
            where ids.Contains(u.Id)
            select new { u.Id, Location = new UnitLocation(p.Id, p.Name, im.Id, im.Name, u.Floor.Name, u.UnitNumber) }
        ).ToDictionaryAsync(x => x.Id, x => x.Location, ct);
    }

    /// <summary>Locations keyed by reservation id.</summary>
    public static async Task<Dictionary<Guid, UnitLocation>> ForReservationsAsync(ApplicationDbContext db, IEnumerable<Guid> reservationIds, CancellationToken ct)
    {
        var ids = reservationIds.Distinct().ToList();
        if (ids.Count == 0) return new();
        var units = await db.Set<Reservation>().Where(r => ids.Contains(r.Id)).Select(r => new { r.Id, r.UnitId }).ToListAsync(ct);
        var locations = await ForUnitsAsync(db, units.Select(u => u.UnitId), ct);
        return units.Where(u => locations.ContainsKey(u.UnitId)).ToDictionary(u => u.Id, u => locations[u.UnitId]);
    }

    public static T WithLocation<T>(this T dto, UnitLocation? location) where T : IHasUnitLocation
    {
        if (location is null) return dto;
        dto.ProjectId = location.ProjectId;
        dto.ProjectName = location.ProjectName;
        dto.ImmeubleId = location.ImmeubleId;
        dto.ImmeubleName = location.ImmeubleName;
        dto.FloorName = location.FloorName;
        dto.UnitNumber = location.UnitNumber;
        return dto;
    }
}
