1	import { expect, test, type Page } from "@playwright/test";
2	import { Api, expectRefused, orNull } from "./support/api";
3	import * as st from "./support/state";
4	import { field, promptAnswers } from "./support/ui";
5	
6	/** Scope 7 — Rendez-vous notaire. */
7	
8	interface NotaryDto {
9	  id: string;
10	  reservationId: string;
11	  notaireId?: string;
12	  appointmentDate: string;
13	  status: string;
14	  outcome?: string | null;
15	  outcomeNote?: string | null;
16	  taxFees: number;
17	  tahfidFees: number;
18	}
19	
20	async function appointment(id: string) {
21	  const admin = await Api.as("globalAdmin");
22	  return admin.get<NotaryDto>(`/api/NotaryAppointments/${id}`);
23	}
24	
25	async function appointmentsOf(reservationId: string) {
26	  const admin = await Api.as("globalAdmin");
27	  return (await admin.all<NotaryDto>("/api/NotaryAppointments")).filter((a) => a.reservationId === reservationId);
28	}
29	
30	const localInput = (d: Date) => new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
31	
32	async function confirmFromList(page: Page, buyerLastName: string) {
33	  await page.goto("/admin/notary-appointments");
34	  const row = page.getByRole("row").filter({ hasText: buyerLastName });
35	  await expect(row).toHaveCount(1);
36	  await row.getByRole("button", { name: "Confirmer" }).click();
37	}
38	
39	test.describe("Acheteur", { tag: "@buyer" }, () => {
40	  test("buyer_appointment_request_created_with_status_requested", async ({ page }) => {
41	    const j = await st.journey("FINAL_VISIT");
42	    await page.goto(`/my/properties/${j.reservationId}`);
43	    await page.getByRole("button", { name: "Demander un RDV notaire" }).click();
44	    const when = new Date(Date.now() + (40 + Math.floor(Math.random() * 300)) * 86400000);
45	    when.setHours(14, 0, 0, 0);
46	    await page.getByLabel("Date et heure souhaitées").fill(localInput(when));
47	    await page.getByRole("button", { name: "Envoyer la demande" }).click();
48	
49	    await expect.poll(async () => (await appointmentsOf(j.reservationId)).length).toBe(1);
50	    const created = (await appointmentsOf(j.reservationId))[0];
51	    expect(created.status).toMatch(/^Requested$/i);
52	    const buyer = await Api.as("buyer", true);
53	    expect((await buyer.get<NotaryDto>(`/api/NotaryAppointments/${created.id}`)).status).toMatch(/^Requested$/i);
54	    const history = page.locator(".card").filter({ has: page.getByRole("heading", { name: "Rendez-vous notaire", exact: true }) });
55	    await expect(history.getByRole("row")).toHaveCount(2); // header + the request
56	  });
57	
58	  test("buyer_cannot_set_purchase_completed", async ({ page }) => {
59	    const j = await st.journey("FINAL_VISIT");
60	    await st.createNotaryAppointment(j);
61	    await st.confirmNotaryAppointment(j);
62	
63	    await page.goto(`/my/properties/${j.reservationId}`);
64	    await expect(page.getByRole("heading", { name: "Rendez-vous notaire", exact: true })).toBeVisible();
65	    await expect(page.getByRole("button", { name: "Enregistrer le résultat" })).toHaveCount(0);
66	    await expect(page.getByText("Achat finalisé")).toHaveCount(0);
67	    await expect(page.getByRole("radio")).toHaveCount(0);
68	
69	    const buyer = await Api.as("buyer", true);
70	    await expectRefused(
71	      await buyer.raw("PUT", `/api/NotaryAppointments/${j.notaryAppointmentId}`, { id: j.notaryAppointmentId, status: "Completed", outcome: "PURCHASE_COMPLETED" }),
72	      [403],
73	      "buyer sets PURCHASE_COMPLETED",
74	    );
75	    const after = await appointment(j.notaryAppointmentId!);
76	    expect(after.outcome ?? null).toBeNull();
77	    expect(after.status).toMatch(/^Confirmed$/i);
78	    const admin = await Api.as("globalAdmin");
79	    expect((await admin.get<{ status: number }>(`/api/Reservations/${j.reservationId}`)).status).toBe(1);
80	  });
81	});
82	
83	for (const [tag, label] of [["@agent", "Agent"], ["@projectAdmin", "Admin projet"], ["@notary", "Notaire"]] as const) {
84	  test.describe(`Confirmation — ${label}`, { tag }, () => {
85	    test("appointment_confirmable_by_agent_admin_or_notary", async ({ page }) => {
86	      const j = await st.journey("FINAL_VISIT");
87	      await st.createNotaryAppointment(j);
88	      await confirmFromList(page, j.buyerLastName);
89	      await expect.poll(async () => (await appointment(j.notaryAppointmentId!)).status).toMatch(/^Confirmed$/i);
90	
91	      if (tag === "@agent") {
92	        // Not everyone: a technician and the buyer are refused.
93	        const other = await st.journey("FINAL_VISIT");
94	        await st.createNotaryAppointment(other);
95	        for (const key of ["technician", "buyer"] as const) {
96	          const api = await Api.as(key, true);
97	          await expectRefused(
98	            await api.raw("PUT", `/api/NotaryAppointments/${other.notaryAppointmentId}`, { id: other.notaryAppointmentId, status: "Confirmed" }),
99	            [403],
100	            `${key} confirms`,
101	          );
102	        }
103	        expect((await appointment(other.notaryAppointmentId!)).status).toMatch(/^Requested$/i);
104	      }
105	    });
106	  });
107	}
108	
109	test.describe("Formulaire — agent", { tag: "@agent" }, () => {
110	  test("appointment_cascade_filters_project_building_floor_unit_reservation", async ({ page }) => {
111	    const a = await st.createProject({
112	      layout: { buildings: [{ suffix: "N1", floors: [{ name: "RDC", units: [{}] }] }, { suffix: "N2", floors: [{ name: "ETAGE2", units: [{}, {}] }] }] },
113	    });
114	    const a1 = await st.createReservation(a, { state: "APPROVED", unitIndex: 0 });
115	    const a2 = await st.createReservation(a, { state: "APPROVED", unitIndex: 1 });
116	    const a3 = await st.createReservation(a, { state: "APPROVED", unitIndex: 2 });
117	    const b = await st.createProject();
118	    const b1 = await st.createReservation(b, { state: "APPROVED" });
119	
120	    await page.goto("/admin/notary-appointments");
121	    await page.getByRole("button", { name: "Demander un RDV notaire" }).click();
122	    const dialog = page.getByRole("dialog", { name: "Demander un rendez-vous notarié" });
123	    const project = field(dialog, "Projet");
124	    const immeuble = field(dialog, "Immeuble");
125	    const floor = field(dialog, "Étage");
126	    const unit = field(dialog, "Unité");
127	    const dossier = field(dialog, "Dossier (réservation approuvée)");
128	    const dossierHas = (id: string) => dossier.locator(`option[value="${id}"]`);
129	
130	    await expect(immeuble).toBeDisabled();
131	    await expect(dossierHas(b1.reservationId)).toHaveCount(1);
132	
133	    // Project A: only its buildings and its dossiers.
134	    await project.selectOption({ label: a.name });
135	    await expect(immeuble.locator("option").filter({ hasText: "e2e-" })).toHaveText([`${a.name}-N1`, `${a.name}-N2`]);
136	    for (const r of [a1, a2, a3]) await expect(dossierHas(r.reservationId)).toHaveCount(1);
137	    await expect(dossierHas(b1.reservationId)).toHaveCount(0);
138	
139	    // Building N2 → its floor, its two units, their dossiers.
140	    await immeuble.selectOption({ label: `${a.name}-N2` });
141	    await expect(floor.locator("option").filter({ hasNotText: /Tous|Choisir/ })).toHaveText(["ETAGE2"]);
142	    await expect(unit.locator("option").filter({ hasNotText: /Toutes|Choisir/ })).toHaveCount(2);
143	    await expect(dossierHas(a1.reservationId)).toHaveCount(0);
144	
