51	        immeublesApi.getById(context.immeuble.id),
52	        immeublesApi.listUnits(context.immeuble.id),
53	      ]);
54	      if (cancelled) return;
55	      setImmeuble(im ?? null);
56	      setUnit(units.find((u) => u.id === unitId) ?? null);
57	    })().catch(() => {
58	      if (!cancelled) setUnit(null);
59	    });
60	
61	    return () => {
62	      cancelled = true;
63	    };
64	  }, [immeubleId, unitId]);
65	
66	  if (unit === undefined) return <Loading />;
67	
68	  return (
69	    <div>
70	      <PageHeader
71	        title={unit ? `Unité ${unit.unitNumber}` : "Parcours de l'unité"}
72	        subtitle={
73	          immeuble
74	            ? `${immeuble.name} · ${immeuble.location}`
75	            : "Cycle de vie commercial — réservation, notaire, vente, livraison, SAV"
76	        }
77	        actions={
78	          immeuble ? (
79	            <Link to={`/admin/immeubles/${immeuble.id}`} className="btn btn-ghost">
80	              ← Retour à l'immeuble
81	            </Link>
82	          ) : undefined
83	        }
84	      />
85	
86	      {unit && (
87	        <div className="stat-grid">
88	          <Card className="stat-card">
89	            <span className="stat-label">Étage</span>
90	            <span className="stat-value">{unit.floor}</span>
91	          </Card>
92	          <Card className="stat-card">
