94	            <span className="stat-value">{unit.numberOfBedrooms ?? "-"}</span>
95	          </Card>
96	          <Card className="stat-card">
97	            <span className="stat-label">Surface</span>
98	            <span className="stat-value">{unit.totalSurface ? `${unit.totalSurface} m²` : "-"}</span>
99	          </Card>
100	          <Card className="stat-card">
101	            <span className="stat-label">Statut</span>
102	            <span className="stat-value">
103	              {/* unit.status IS the authoritative source (UnitStatusService is the
104	                  single writer, §3/§7) — it was fetched into `unit` above but never
105	                  read here. The previous reservation-derived heuristic could show
106	                  "Available" on a unit that was genuinely HOLD_PENDING_APPROVAL/
107	                  RESERVED/etc. whenever its own client-side reservation lookup
108	                  missed the record (N6): a real desync between what this badge
109	                  claimed and what every transition actually gates on. */}
110	              {unit.status ? <StatusBadge status={unit.status} /> : <StatusBadge status="AVAILABLE" />}
111	            </span>
