import path from "node:path";

/**
 * Test accounts on the QA databases (GPIA_Auth_QA / GPIA_Project_QA).
 *
 * All share E2E_PASSWORD (default below matches the QA reset). Accounts that
 * do not exist yet (second buyer, tech lead) are created by auth.setup.ts
 * through POST /api/User/admin-create.
 */
import fs from "node:fs";

/**
 * Shared password of the QA test accounts. Never committed: read from the
 * E2E_PASSWORD environment variable, or from the git-ignored tests/.env.e2e
 * file (a single line `E2E_PASSWORD=...`).
 */
function readPassword(): string {
  if (process.env.E2E_PASSWORD) return process.env.E2E_PASSWORD;
  const file = path.resolve("tests", ".env.e2e");
  if (fs.existsSync(file)) {
    const line = fs.readFileSync(file, "utf-8").split(/?
/).find((l) => l.startsWith("E2E_PASSWORD="));
    if (line) return line.slice("E2E_PASSWORD=".length).trim();
  }
  throw new Error("E2E_PASSWORD is not set (environment variable or tests/.env.e2e).");
}

export const E2E_PASSWORD = readPassword();

export const AUTH_API = process.env.E2E_AUTH_API ?? "http://localhost:48988";
export const PROJECT_API = process.env.E2E_PROJECT_API ?? "http://localhost:48989";

export type RoleKey =
  | "globalAdmin"
  | "projectAdmin"
  | "agent"
  | "agentOther"
  | "buyer"
  | "buyerOther"
  | "notary"
  | "technician"
  | "technicianOther"
  | "techLead";

export interface Account {
  key: RoleKey;
  userName: string;
  email: string;
  /** Spec §6.1 role code this account must carry. */
  role: string;
  /** Created by the setup project when missing. */
  provision?: { firstName: string; lastName: string; phone: string };
}

export const ACCOUNTS: Record<RoleKey, Account> = {
  globalAdmin: { key: "globalAdmin", userName: "e2e.admin", email: "e2e.admin@qa.local", role: "GLOBAL_ADMIN" },
  projectAdmin: { key: "projectAdmin", userName: "gpia.padmin", email: "gpia.padmin@test.local", role: "PROJECT_ADMIN" },
  agent: { key: "agent", userName: "e2e.agent", email: "e2e.agent@qa.local", role: "SALES_AGENT" },
  agentOther: { key: "agentOther", userName: "gpia.agent", email: "gpia.agent@test.local", role: "SALES_AGENT" },
  buyer: { key: "buyer", userName: "e2e.buyer", email: "e2e.buyer@qa.local", role: "BUYER" },
  buyerOther: {
    key: "buyerOther",
    userName: "e2e.buyer2@qa.local",
    email: "e2e.buyer2@qa.local",
    role: "BUYER",
    provision: { firstName: "Salma", lastName: "Autre", phone: "+212600000102" },
  },
  notary: { key: "notary", userName: "e2e.notary", email: "e2e.notary@qa.local", role: "NOTARY" },
  technician: { key: "technician", userName: "e2e.tech", email: "e2e.tech@qa.local", role: "TECHNICIAN" },
  technicianOther: { key: "technicianOther", userName: "gpia.tech", email: "gpia.tech@test.local", role: "TECHNICIAN" },
  techLead: {
    key: "techLead",
    userName: "e2e.techlead@qa.local",
    email: "e2e.techlead@qa.local",
    role: "TECH_LEAD",
    provision: { firstName: "Rachid", lastName: "Responsable", phone: "+212600000103" },
  },
};

// package.json is "type": "module", so there is no __dirname; the suite is
// always launched from the repository root.
const AUTH_DIR = path.resolve("tests", ".auth");

export const storageStateFor = (key: RoleKey) => path.join(AUTH_DIR, `${key}.json`);

/** Roles that get their own Playwright project (UI sessions). */
export const ROLE_PROJECTS: { project: string; tag: string; key: RoleKey; storageState: string }[] = (
  [
    ["global-admin", "@globalAdmin", "globalAdmin"],
    ["project-admin", "@projectAdmin", "projectAdmin"],
    ["agent", "@agent", "agent"],
    ["buyer", "@buyer", "buyer"],
    ["notary", "@notary", "notary"],
    ["technician", "@technician", "technician"],
    ["tech-lead", "@techLead", "techLead"],
  ] as const
).map(([project, tag, key]) => ({ project, tag, key, storageState: storageStateFor(key) }));

